import React, { useState, useMemo } from 'react';
import WeatherContextChart from '../WeatherContextChart';
import { usePollenContext } from '../DataProvider';
import { 
  ARCHIVE_2025, 
  WEATHER_ARCHIVE_2023, 
  WEATHER_ARCHIVE_2024, 
  WEATHER_ARCHIVE_2025, 
  WEATHER_ARCHIVE_2026
} from '../data';
import { 
  chartOptionsCommon, 
  formatMonth, 
  safeVal 
} from '../components/ChartUtils';
import SeasonComparisonWidget from '../components/SeasonComparisonWidget';
import PollenHeatmapWidget from '../components/PollenHeatmapWidget';
import StaticSummaryWidget from '../components/StaticSummaryWidget';

const TabHistory = ({ isMobile }) => {
  const { historyData } = usePollenContext();

  const [archiveRange, setArchiveRange] = useState('season'); 
  const [archivePollenChartType, setArchivePollenChartType] = useState('bar'); 
  const [archivePollenScaleType, setArchivePollenScaleType] = useState('logarithmic'); 
  const [activeYears, setActiveYears] = useState(['2026', '2025']);
  const [activeAllergens, setActiveAllergens] = useState(['birch']);

  const filteredArchiveKeys = useMemo(() => {
    const archiveKeys = Object.keys(ARCHIVE_2025).filter(k => /^\d{2}-\d{2}$/.test(k));
    const historyKeys = historyData.map(d => d && typeof d.date === 'string' ? d.date.substring(5) : null).filter(Boolean);
    const rawKeys = [...new Set([...archiveKeys, ...historyKeys])].sort();
    
    if (rawKeys.length === 0) return [];
    
    const startStr = rawKeys[0];
    const endStr = rawKeys[rawKeys.length - 1];
    
    const allKeys = [];
    const current = new Date(`2024-${startStr}T00:00:00Z`); 
    const end = new Date(`2024-${endStr}T00:00:00Z`);
    
    while (current <= end) {
      const m = String(current.getUTCMonth() + 1).padStart(2, '0');
      const d = String(current.getUTCDate()).padStart(2, '0');
      allKeys.push(`${m}-${d}`);
      current.setUTCDate(current.getUTCDate() + 1);
    }

    const now = new Date();

    if (archiveRange === 'season') {
      const historyMap = new Map();
      historyData.forEach(d => historyMap.set(d.date, d));

      let firstActiveIndex = -1;
      let lastActiveIndex = -1;

      for (let i = 0; i < allKeys.length; i++) {
        const k = allKeys[i];
        let hasData = false;
        for (const allergen of activeAllergens) {
          for (const year of activeYears) {
            const record = historyMap.get(`${year}-${k}`);
            if (record && (record[allergen] > 0 || record.tempAvg !== undefined || record.precip !== undefined)) { hasData = true; break; }
            const dataKey = year === '2025' ? allergen : `${allergen}_${year}`;
            if (ARCHIVE_2025[k]?.[dataKey] > 0) { hasData = true; break; }
          }
          if (hasData) break;
        }
        if (hasData) {
          if (firstActiveIndex === -1) firstActiveIndex = i;
          lastActiveIndex = i;
        }
      }

      if (firstActiveIndex !== -1 && lastActiveIndex !== -1) {
        const startIdx = Math.max(0, firstActiveIndex - 3); 
        const endIdx = Math.min(allKeys.length, lastActiveIndex + 4); 
        return allKeys.slice(startIdx, endIdx);
      }
      return allKeys;
    }
    if (archiveRange === 'month') {
      const targetMonth = String(now.getMonth() + 1).padStart(2, '0');
      const monthKeys = allKeys.filter(k => k.startsWith(targetMonth));
      return monthKeys.length > 0 ? monthKeys : allKeys.filter(k => k.startsWith('04')); 
    }
    if (archiveRange === 'week') {
      const last7Days = [...Array(7)].map((_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - i);
        return `${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
      });
      const weekKeys = allKeys.filter(k => last7Days.includes(k.substring(0, 5)));
      return weekKeys.length > 0 ? weekKeys : allKeys.slice(-7); 
    }
    return allKeys;
  }, [archiveRange, historyData, activeAllergens, activeYears]);

  const archiveLabels = useMemo(() => {
    return filteredArchiveKeys.map(k => `${parseInt(k.split('-')[1], 10)} ${formatMonth(k.split('-')[0])}`);
  }, [filteredArchiveKeys]);

  const archiveChartData = useMemo(() => {
    const datasets = [];
    const allergenNames = { 'alder': 'Ольха', 'hazel': 'Орешник', 'birch': 'Береза', 'oak': 'Дуб' };
    activeAllergens.forEach(allergen => {
      activeYears.forEach(year => {
        const isSingleAllergen = activeAllergens.length === 1;
        
        let borderColor, backgroundColor, borderDash;
        
        const getSolidDarkColor = (baseHex, yearStr) => {
          if (yearStr === '2026') return baseHex;
          const palettes = {
            '#32D74B': { '2025': '#166534', '2024': '#14532d', '2023': '#064e3b' }, 
            '#FFD60A': { '2025': '#a16207', '2024': '#854d0e', '2023': '#713f12' }, 
            '#FF453A': { '2025': '#b91c1c', '2024': '#991b1b', '2023': '#7f1d1d' }, 
            '#15803d': { '2025': '#166534', '2024': '#14532d', '2023': '#064e3b' }, 
            '#64D2FF': { '2025': '#0369a1', '2024': '#075985', '2023': '#082f49' }, 
            '#FF8A65': { '2025': '#c2410c', '2024': '#9a3412', '2023': '#7c2d12' }  
          };
          return palettes[baseHex]?.[yearStr] || baseHex;
        };
        
        if (isSingleAllergen) {
          const yearColors = { '2026': '#64D2FF', '2025': '#FFD60A', '2024': '#FF8A65', '2023': '#32D74B' };
          borderColor = getSolidDarkColor(yearColors[year] || '#ffffff', year);
          backgroundColor = archivePollenChartType === 'bar' ? borderColor : 'transparent';
          borderDash = ['2026', '2025'].includes(year) ? [] : [4, 4];
        } else {
          const allergenColors = { 'alder': '#32D74B', 'hazel': '#FFD60A', 'birch': '#FF453A', 'oak': '#15803d' };
          const yearDashes = { '2026': [], '2025': [], '2024': [4, 4], '2023': [2, 4] };
          
          borderColor = getSolidDarkColor(allergenColors[allergen] || '#ffffff', year);
          backgroundColor = archivePollenChartType === 'bar' ? borderColor : 'transparent';
          borderDash = yearDashes[year] || [];
        }

        const isCurrentYear = year === '2026';
        const lineThickness = isCurrentYear ? (isMobile ? 2.5 : 3.5) : (isMobile ? 1.5 : 2.5);
        const zIndexOrder = { '2026': 1, '2025': 2, '2024': 3, '2023': 4 };

        datasets.push({
          label: `${allergenNames[allergen]} (${year})`,
          data: filteredArchiveKeys.map(k => {            
            let val = null;
            const record = historyData.find(d => d && d.date === `${year}-${k}`);
            if (record && record[allergen] !== undefined && record[allergen] !== null) {
              val = record[allergen];
            } else {
              const dataKey = year === '2025' ? allergen : `${allergen}_${year}`;
              val = ARCHIVE_2025[k]?.[dataKey] ?? null;
            }
            val = safeVal(val, archivePollenScaleType);
            return val;
          }),
          type: archivePollenChartType,
          order: zIndexOrder[year], 
          borderColor,
          backgroundColor,
          borderDash,
          fill: false,
          tension: 0.4,
          pointRadius: isMobile ? (isCurrentYear ? 2 : 0) : (isCurrentYear ? 4 : 2),
          pointHoverRadius: isMobile ? 4 : 6,
          borderWidth: archivePollenChartType === 'bar' ? 0 : lineThickness,
          ...(archivePollenChartType === 'bar' && {
            barPercentage: 0.85,      
            categoryPercentage: 0.75, 
            borderRadius: { topLeft: 3, topRight: 3, bottomLeft: 0, bottomRight: 0 }, 
          }),
        });
      });
    });
    return {
      labels: archiveLabels,
      datasets: datasets
    };
  }, [archiveLabels, activeAllergens, activeYears, archivePollenChartType, historyData, archivePollenScaleType, isMobile, filteredArchiveKeys]);

  return (
    <>
      <SeasonComparisonWidget 
        archiveRange={archiveRange} setArchiveRange={setArchiveRange}
        archivePollenChartType={archivePollenChartType} setArchivePollenChartType={setArchivePollenChartType}
        archivePollenScaleType={archivePollenScaleType} setArchivePollenScaleType={setArchivePollenScaleType}
        activeYears={activeYears} setActiveYears={setActiveYears}
        activeAllergens={activeAllergens} setActiveAllergens={setActiveAllergens}
        archiveChartData={archiveChartData}
      />

      <PollenHeatmapWidget 
        activeAllergens={activeAllergens}
        activeYears={activeYears}
        archiveLabels={archiveLabels}
        archiveChartData={archiveChartData}
        isMobile={isMobile}
      />

      <WeatherContextChart 
        filteredArchiveKeys={filteredArchiveKeys}
        archiveLabels={archiveLabels}
        isMobile={isMobile}
        chartOptionsCommon={chartOptionsCommon}
        weatherData2023={WEATHER_ARCHIVE_2023}
        weatherData2024={WEATHER_ARCHIVE_2024}
        weatherData2025={WEATHER_ARCHIVE_2025}
        weatherData2026={WEATHER_ARCHIVE_2026}
        historyData={historyData}
      />

      <StaticSummaryWidget />
    </>
  );
};

export default TabHistory;
