import React, { createContext, useContext } from 'react';
import { useMeasurements } from './useMeasurements';
import { useWeather } from './useWeather';
import { usePollenRisk } from './usePollenRisk';
import { ARCHIVE_2026_DATA } from './data';

const PollenContext = createContext();

export const usePollenContext = () => {
  const context = useContext(PollenContext);
  if (!context) {
    throw new Error('usePollenContext must be used within a PollenProvider');
  }
  return context;
};

export const PollenProvider = ({ children }) => {
  const { 
    historyData: dbHistoryData, 
    latestData: dbLatestData, 
    fetchMeasurements 
  } = useMeasurements();

  const { 
    forecastData, 
    currentWeather, 
    isLoading: isWeatherLoading 
  } = useWeather();

  const historyData = dbHistoryData.length > 0 
    ? dbHistoryData 
    : Object.entries(ARCHIVE_2026_DATA).map(([date, data]) => ({ date, ...data })).reverse();
  
  const latestData = dbLatestData || historyData[0];

  const firstRealIndex = historyData.findIndex(d => 
    typeof d.alder === 'number' || typeof d.hazel === 'number' || typeof d.birch === 'number' ||
    typeof d.grass === 'number' || typeof d.weed === 'number' || typeof d.clado === 'number' || typeof d.alt === 'number'
  );

  let validHistory = historyData;
  if (firstRealIndex > 0) {
    validHistory = historyData.slice(firstRealIndex);
  }

  const activeLatestData = validHistory[0] || latestData;
  const currentRisk = usePollenRisk(activeLatestData);

  const value = {
    historyData,
    dbHistoryData,
    validHistory,
    latestData,
    activeLatestData,
    currentRisk,
    fetchMeasurements,
    forecastData,
    currentWeather,
    isWeatherLoading
  };

  return (
    <PollenContext.Provider value={value}>
      {children}
    </PollenContext.Provider>
  );
};
