import React from 'react';
import { Microscope, Plus } from 'lucide-react'; // Keep Plus for the button if it's used directly
import { getRiskLevel } from '../usePollenRisk';
// import AddAllergensFromTrapButton from './AddAllergensFromTrapButton'; // This component is now integrated directly
import { AllergenIcons } from './ui/AllergenIcons';

const CurrentDataWidget = ({ activeLatestData, currentRisk, role, setEditData, setIsModalOpen }) => {
  if (!activeLatestData) {
    return <div className="empty-state">Данных с ловушек за сегодня пока нет 🤷‍♂️</div>;
  }

  const activeAllergens = [
    { id: 'alder', name: 'Ольха', icon: AllergenIcons.alder, color: '#32D74B' },
    { id: 'hazel', name: 'Орешник', icon: AllergenIcons.hazel, color: '#FFD60A' },
    { id: 'birch', name: 'Береза', icon: AllergenIcons.birch, color: '#FF453A' },
    { id: 'oak', name: 'Дуб', icon: AllergenIcons.oak, color: '#15803d' }
  ].filter(item => {
    const val = activeLatestData[item.id];
    return val !== null && val !== undefined && val !== '' && val !== '-';
  });

  return (
    <div className="card overflow-hidden w-full">
      <div className="risk-header" style={{ marginBottom: 15, alignItems: 'flex-start' }}>
        <div>
          <h3 className="section-title" style={{ marginBottom: 2 }}><Microscope size={18} /> Данные ловушек</h3>
          <div style={{ fontSize: 11, color: 'var(--text-secondary)', marginLeft: 26 }}>Дата измерений: {activeLatestData.date.split('-').reverse().join('.')}</div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <div className={`risk-badge ${currentRisk.level === 'high' || currentRisk.level === 'critical' ? 'breathe-effect' : ''}`} style={{ background: currentRisk.bg, color: currentRisk.color, '--breathe-color': currentRisk.color, flexShrink: 0 }}>
            {currentRisk.label}
          </div>
          {role !== 'viewer' && (
            <button 
              className="add-data-btn" 
              onClick={() => { setEditData(null); setIsModalOpen(true); }}
              title="Внести данные с ловушки"
            >
              <Plus size={18} />
            </button>
          )}
        </div>
      </div>
      <div className="pollen-list" style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        {activeAllergens.length === 0 ? (
          <div className="empty-state" style={{ color: 'var(--text-secondary)', textAlign: 'center', padding: '12px 0' }}>Нет данных о пыльце за этот период</div>
        ) : (
          activeAllergens.map(item => {
            const val = activeLatestData[item.id];
            const itemRisk = getRiskLevel({ [item.id]: val });
            return (
              <div className="pollen-item" key={item.id} style={{ opacity: 1 }}>
                <div className="pollen-left" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <div className="pollen-icon-wrapper" style={{ background: itemRisk.bg, color: '#ffffff' }}>
                    <item.icon size={20} className="pollen-anim-icon" />
                  </div>
                  <div className="pollen-name">{item.name}</div>
                </div>
                <div className="pollen-right">
                  <div className="pollen-value" style={{ color: itemRisk.color }}><>{val} <span style={{ fontSize: 12, color: 'var(--text-secondary)', fontWeight: 'normal' }}>ед/м³</span></></div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default CurrentDataWidget;