import React from 'react';
import { motion } from 'framer-motion';
import { Sun, Cloud, CloudRain, CloudSnow, CloudLightning, CalendarDays } from 'lucide-react';

// ИСПРАВЛЕНО: Умный анализатор тренда пыльцы на основе минимальной влажности
const getTrend = (dayForecast, isMobile) => {
  if (!dayForecast) return { text: 'Нет данных', color: '#8e8e93', bg: 'rgba(142, 142, 147, 0.15)' };
  
  const precip = dayForecast.precip || 0;
  const windMax = dayForecast.windMax || 0;
  const tempMax = dayForecast.tempMax !== undefined ? dayForecast.tempMax : (dayForecast.tempAvg || 0);
  const humidityMin = dayForecast.humidityMin || 50; // Используем минимум!

  // УМНЫЕ СОКРАЩЕНИЯ: Короткий текст для телефона, длинный для ПК
  if (precip >= 1.0) return { text: isMobile ? 'Смывает' : 'Дождь прибьет', color: '#32D74B', bg: 'rgba(50, 215, 75, 0.15)' };
  
  if (windMax >= 5 && humidityMin <= 45 && precip < 0.5) return { text: isMobile ? 'Ветер' : 'Сухой ветер', color: '#FF453A', bg: 'rgba(255, 69, 58, 0.15)' };
  
  if (tempMax >= 12 && humidityMin <= 50) return { text: isMobile ? 'Пыление' : 'Активный лёт', color: '#FF9F0A', bg: 'rgba(255, 159, 10, 0.15)' };
  
  if (tempMax < 5) return { text: isMobile ? 'Спит' : 'Сдерживает', color: '#64D2FF', bg: 'rgba(100, 210, 255, 0.15)' };
  
  return { text: 'Умеренно', color: '#FFD60A', bg: 'rgba(255, 214, 10, 0.15)' };
};

const getWeatherIcon = (code) => {
  if (code === undefined) return <Cloud size={24} color="#8e8e93" />;
  if (code <= 1) return <Sun size={24} color="#FFD60A" />;
  if (code <= 3) return <Cloud size={24} color="#EBEBF5" />;
  if (code >= 51 && code <= 67) return <CloudRain size={24} color="#64D2FF" />;
  if (code >= 71 && code <= 77) return <CloudSnow size={24} color="#ffffff" />;
  if (code >= 95) return <CloudLightning size={24} color="#FFD60A" />;
  return <Cloud size={24} color="#8e8e93" />;
};

const getDayName = (dateStr, isMobile) => {
  const date = new Date(dateStr);

  if (isMobile) {
    // Мобилка: короткий день + число (например, "Пт, 24")
    return date.toLocaleDateString('ru-RU', {
      weekday: 'short',
      day: 'numeric'
    });
  }

  // Десктоп: полный день + число + месяц (например, "Пятница, 24 апр")
  return date.toLocaleDateString('ru-RU', {
    weekday: 'long',
    day: 'numeric',
    month: 'short'
  });
};

const ForecastWidget = ({ forecastData, currentWeather, isLoading, isError, isMobile = false }) => {
  if (isLoading) {
    return (
      <div className="card" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '160px' }}>
        <span style={{ color: 'var(--text-secondary)' }}>Загрузка прогноза...</span>
      </div>
    );
  }

  if (isError || !forecastData || forecastData.length === 0) {
    return (
      <div className="card" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '160px' }}>
        <span style={{ color: 'var(--critical)' }}>Ошибка загрузки погоды</span>
      </div>
    );
  }

  const nextDays = forecastData.slice(0, 4);

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="card" style={{ overflow: 'hidden', padding: 0, marginBottom: '16px' }}>
      <div style={{ padding: '16px 20px', borderBottom: '1px solid rgba(255,255,255,0.05)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h3 style={{ margin: 0, fontSize: '16px', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <CalendarDays size={18} color="var(--accent)" />
          Аллерго-прогноз
        </h3>
      </div>
      
      <div style={{ display: 'flex', padding: '16px 12px', gap: '8px', overflowX: 'auto' }} className="custom-scrollbar">
        {nextDays.map((day, index) => {
          const trend = getTrend(day, isMobile);
          const displayTMax = day.tempMax > 0 ? `+${Math.round(day.tempMax)}°` : `${Math.round(day.tempMax)}°`;
          const displayTMin = day.tempMin > 0 ? `+${Math.round(day.tempMin)}°` : `${Math.round(day.tempMin)}°`;

          return (
            <div key={day.date} style={{ 
              flex: '1 0 22%', minWidth: '85px', 
              background: 'rgba(255,255,255,0.03)', 
              borderRadius: '12px', 
              padding: '12px 8px', 
              display: 'flex', 
              flexDirection: 'column', 
              alignItems: 'center',
              border: index === 0 ? `2px solid ${trend.color}` : '1px solid rgba(255,255,255,0.08)',
              boxShadow: index === 0 ? `0 0 15px ${trend.color}20` : 'none',
            }}>
              {/* День недели */}
              <span style={{ fontSize: '13px', fontWeight: 600, color: 'rgba(235, 235, 245, 0.8)', marginBottom: '8px' }}>
                {getDayName(day.date, isMobile)}
              </span>
              
              {/* Погода */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '12px' }}>
                {getWeatherIcon(day.weathercode)}
                <div style={{ display: 'flex', flexDirection: 'column' }}>
                  <span style={{ fontSize: '15px', fontWeight: 800, color: '#fff', lineHeight: 1 }}>{displayTMax}</span>
                  <span style={{ fontSize: '11px', fontWeight: 600, color: 'rgba(235,235,245,0.4)', lineHeight: 1, marginTop: '2px' }}>{displayTMin}</span>
                </div>
              </div>

              {/* Аллерго-тренд */}
              <div style={{ 
                background: trend.bg, 
                border: `1px solid ${trend.color}40`, 
                borderRadius: '8px', 
                padding: '4px 8px',
                display: 'flex', alignItems: 'center',
                width: '100%', justifyContent: 'center'
              }}>
                <span style={{ fontSize: '10px', fontWeight: 800, color: trend.color, whiteSpace: 'nowrap' }}>{trend.text}</span>
              </div>
            </div>
          );
        })}
      </div>
    </motion.div>
  );
};

export default ForecastWidget;