import { useMemo } from 'react';

/**
 * Определяет уровень риска и соответствующие UI-параметры на основе данных о пыльце.
 * @param {object} data - Объект с данными о концентрации пыльцы (например, { birch: 100, alder: 50 }).
 * @returns {object} - Объект с уровнем риска, меткой и цветами.
 */
export const getRiskLevel = (data) => {
  if (!data) {
    return { level: 'safe', label: 'НЕТ ДАННЫХ', color: 'var(--text-secondary)', bg: 'rgba(255,255,255,0.1)' };
  }

  const isAllNull = ['alder', 'hazel', 'birch', 'oak'].every(k => data[k] === null || data[k] === undefined);
  if (isAllNull) {
    return { level: 'safe', label: 'НЕТ ДАННЫХ', color: 'var(--text-secondary)', bg: 'rgba(255,255,255,0.1)' };
  }

  const total = (data.alder || 0) + (data.hazel || 0) + (data.birch || 0) + (data.oak || 0);

  if (total >= 500) {
    return { level: 'extreme', label: 'ЭКСТРЕМАЛЬНАЯ УГРОЗА', color: '#AF52DE', bg: 'rgba(175, 82, 222, 0.15)' };
  }
  if (total >= 100) {
    return { level: 'critical', label: 'КРИТИЧЕСКИЙ', color: 'var(--critical)', bg: 'rgba(255, 69, 58, 0.15)' };
  }
  if (total >= 50) {
    return { level: 'high', label: 'ВЫСОКИЙ РИСК', color: '#FF9500', bg: 'rgba(255, 149, 0, 0.15)' };
  }
  if (total >= 10) {
    return { level: 'warning', label: 'УМЕРЕННО', color: '#FFCC00', bg: 'rgba(255, 204, 0, 0.15)' };
  }
  return { level: 'safe', label: 'БЕЗОПАСНО', color: 'var(--safe)', bg: 'rgba(50, 215, 75, 0.15)' };
};

export const usePollenRisk = (data) => {
  return useMemo(() => getRiskLevel(data), [data]);
};