import React, { useState } from 'react';
import { CloudRain, Zap } from 'lucide-react';
import { Bar } from 'react-chartjs-2';
import { motion } from 'framer-motion';

import { useWeatherChartData, YEAR_COLORS } from './hooks/useWeatherChartData';
import LegendPill from './components/ui/LegendPill';
import SegmentControl from './components/ui/SegmentControl';

const WeatherContextChart = React.memo(({
  isMobile = false,
  weatherData2023 = {}, weatherData2024 = {}, weatherData2025 = {}, weatherData2026 = {},
  historyData = [] // Use historyData passed from TabHistory
}) => {
  const [weatherScaleType, setWeatherScaleType] = useState('linear');
  const [weatherVis, setWeatherVis] = useState({
    temp: true, precip: true, humidity: true, '2026': true, '2025': false, '2024': false, '2023': false
  });

  const { weatherArchiveChartData, weatherChartOptions } = useWeatherChartData({
    weatherData2023, weatherData2024, weatherData2025, weatherData2026,
    historyData: historyData, // Pass historyData to hook
    weatherScaleType, weatherVis
  });

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="card" style={{ marginBottom: '20px', padding: 0, overflow: 'hidden' }}>
      <div className="chart-header">
        <h3 className="chart-header-title"><CloudRain size={20} color="#64D2FF" /> Метео-контекст</h3>
        <SegmentControl 
          options={[{label: 'LIN', value: 'linear'}, {label: 'LOG', value: 'logarithmic'}]}
          activeOption={weatherScaleType}
          onChange={setWeatherScaleType}
          style={{ width: 90, height: 28 }}
        />
      </div>
      <div style={{ padding: '0 20px 20px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '16px', borderBottom: '1px solid rgba(255,255,255,0.06)', paddingBottom: '12px' }}>
          <LegendPill label={isMobile ? "Темп." : "Температура"} color="#ffffff" isActive={weatherVis.temp} onClick={() => setWeatherVis(p => ({...p, temp: !p.temp}))} />
          <LegendPill label="Осадки" color="#a1a1aa" isActive={weatherVis.precip} onClick={() => setWeatherVis(p => ({...p, precip: !p.precip}))} icon={<CloudRain size={14}/>} />
          <LegendPill label={isMobile ? "Влажн." : "Влажность (Мин)"} color="#64D2FF" isActive={weatherVis.humidity} onClick={() => setWeatherVis(p => ({...p, humidity: !p.humidity}))} isDashed />
        </div>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '16px' }}>
          {['2026', '2025', '2024', '2023'].map(year => (
            <LegendPill key={year} label={`${year} год`} color={YEAR_COLORS[year]} isActive={weatherVis[year]} onClick={() => setWeatherVis(p => ({...p, [year]: !p[year]}))} icon={year === '2026' ? <Zap size={14} fill={YEAR_COLORS[year]}/> : null} />
          ))}
        </div>
      </div>
      <div style={{ position: 'relative', width: '100%', padding: '0 10px 10px' }}>
        <div className="chart-scroll-wrapper custom-scrollbar">
          <div className="chart-container" style={{ height: isMobile ? '280px' : '340px' }}><Bar data={weatherArchiveChartData} options={weatherChartOptions} /></div>
        </div>
      </div>
    </motion.div>
  );
});

export default WeatherContextChart;