import React from 'react';
import WeatherWidget from '../WeatherWidget';
import { usePollenContext } from '../DataProvider';

const Header = ({ activeTab, setActiveTab, role }) => {
  const { currentWeather, forecastData, isWeatherLoading, activeLatestData } = usePollenContext();

  const tabs = [
    { label: 'СЕГОДНЯ', value: 0 },
    { label: 'АРХИВ', value: 1 }
  ];

  if (role === 'admin') {
    tabs.push({ label: 'АДМИН', value: 2 });
  }

  return (
    <header className="header relative" style={{ position: 'relative', paddingBottom: '16px' }}>
      <div className="header-top" style={{ display: 'flex', gap: '8px', alignItems: 'center', justifyContent: 'space-between', position: 'relative' }}>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexShrink: 0, zIndex: 2 }}>
          <div style={{ background: '#151517', border: '1px solid rgba(255, 255, 255, 0.08)', borderRadius: '12px', padding: '8px 14px', fontSize: '16px', fontWeight: 700, color: '#fff' }}>
            Москва
          </div>
          <div style={{ background: '#151517', border: '1px solid rgba(255, 255, 255, 0.08)', borderRadius: '12px', padding: '8px 14px', fontSize: '13px', fontWeight: 500, color: 'var(--text-secondary)' }}>
            {new Date().toLocaleDateString('ru-RU', {day:'numeric', month:'long'})}
          </div>
        </div>
        
        <div style={{ display: 'flex', gap: '24px', position: 'absolute', left: '50%', transform: 'translateX(-50%)', zIndex: 1 }}>
          {tabs.map(tab => (
            <button
              key={tab.value}
              onClick={() => setActiveTab(tab.value)}
              style={{
                background: 'transparent',
                border: 'none',
                padding: '8px 0',
                cursor: 'pointer',
                fontSize: '14px',
                fontWeight: 600,
                letterSpacing: '1px',
                transition: 'all 0.3s ease',
                color: activeTab === tab.value ? '#fff' : 'rgba(255, 255, 255, 0.4)',
                textShadow: activeTab === tab.value ? '0 0 12px rgba(255, 255, 255, 0.8)' : 'none',
                outline: 'none',
                whiteSpace: 'nowrap'
              }}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div style={{ flexShrink: 0, zIndex: 2 }}>
          <WeatherWidget 
            weather={currentWeather} 
            forecastData={forecastData} 
            loading={isWeatherLoading} 
            pollenData={activeLatestData} 
          />
        </div>
      </div>
    </header>
  );
};

export default Header;
