import { useState, useEffect, useCallback } from 'react';

export const useWeather = (lat = 55.75, lon = 37.62) => {
  const [forecastData, setForecastData] = useState([]);
  const [currentWeather, setCurrentWeather] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isError, setIsError] = useState(false);

  const fetchForecast = useCallback(async () => {
      setIsLoading(true);
      setIsError(false);
      try {
        // ИСПРАВЛЕНО: Запрашиваем relative_humidity_2m_min вместо тяжелого hourly массива
        const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current_weather=true&daily=weathercode,temperature_2m_max,temperature_2m_min,precipitation_sum,windspeed_10m_max,relative_humidity_2m_min&timezone=Europe%2FMoscow&forecast_days=10&windspeed_unit=ms`;
        const res = await fetch(url);
        if (!res.ok) throw new Error("Сетевая ошибка или API недоступно");
        const data = await res.json();
        
        if (data && data.current_weather) {
          setCurrentWeather(data.current_weather);
        }

        if (data && data.daily) {
          // ЗАДАЧА 1: Исправлен баг с UTC и сдвигом дат
          const now = new Date();
          const offset = now.getTimezoneOffset() * 60000;
          const todayStr = new Date(now - offset).toISOString().split('T')[0];

          const formatted = data.daily.time
            .map((date, i) => {
              const tempMax = data.daily.temperature_2m_max[i];
              const tempMin = data.daily.temperature_2m_min[i];
              const tempAvg = Math.round((tempMax + tempMin) / 2);
              const precip = data.daily.precipitation_sum[i] || 0;
              const windMax = Math.round(data.daily.windspeed_10m_max[i] || 0);
              const weathercode = data.daily.weathercode ? data.daily.weathercode[i] : undefined;
              
              // ИСПРАВЛЕНО: Берем минимальную влажность напрямую из API (если нет, ставим 50)
              const humidityMin = data.daily.relative_humidity_2m_min[i] || 50;

              return { date, tempMax, tempMin, tempAvg, precip, windMax, humidityMin, weathercode };
            })
            // ЗАДАЧА 1: Отображаем сегодняшний день, а не начинаем с завтрашнего
            .filter(item => item.date >= todayStr);
          setForecastData(formatted);
        }
      } catch (e) {
        console.error("Ошибка при получении прогноза погоды:", e);
        setIsError(true);
      } finally {
        setIsLoading(false);
      }
  }, [lat, lon]);

  useEffect(() => {
    fetchForecast();
    const interval = setInterval(fetchForecast, 3600000);
    return () => clearInterval(interval);
  }, [fetchForecast]);

  return { forecastData, currentWeather, isLoading, isError, refetch: fetchForecast };
};