import React from 'react';
import SeasonProgressWidget from '../SeasonProgressWidget';
import ForecastWidget from '../ForecastWidget';
import DayInHistoryWidget from '../widgets/DayInHistoryWidget';
import { usePollenContext } from '../DataProvider';
import CurrentDataWidget from '../components/CurrentDataWidget';
import DynamicsChartWidget from '../components/DynamicsChartWidget';

const TabToday = ({ isMobile, role, setIsModalOpen, setEditData }) => {
  const { forecastData, historyData, activeLatestData, currentRisk, validHistory } = usePollenContext();

  return (
    <>
      <SeasonProgressWidget 
        forecastData={forecastData}
        historyData={historyData}
      />

      <CurrentDataWidget 
        activeLatestData={activeLatestData}
        currentRisk={currentRisk}
        role={role}
        setEditData={setEditData}
        setIsModalOpen={setIsModalOpen}
      />

      <DayInHistoryWidget historyData={historyData} />

      <ForecastWidget forecastData={forecastData} isMobile={isMobile} />

      <DynamicsChartWidget validHistory={validHistory} isMobile={isMobile} />
    </>
  );
};

export default TabToday;
