import React, { useEffect, useMemo } from 'react';
import { motion, useMotionValue, useTransform, animate } from 'framer-motion';
import { useIsMobile } from './hooks/useIsMobile';

const AnimatedNumber = React.memo(({ value, padZero = false, delay = 0 }) => {
  const progress = useMotionValue(0);
  const formatted = useTransform(progress, (latest) => {
    if (latest < 0.6) {
      const rand = Math.floor(Math.random() * 99);
      return padZero ? String(rand).padStart(2, '0') : rand.toString();
    }
    const val = Math.round(value * ((latest - 0.6) / 0.4));
    return padZero ? String(val).padStart(2, '0') : val.toLocaleString('ru-RU');
  });
  const textShadow = useTransform(progress, [0, 0.4, 0.7, 1], ['0 -18px 24px rgba(255,255,255,0.45), 0 18px 24px rgba(255,255,255,0.45)', '0 -8px 12px rgba(255,255,255,0.2), 0 8px 12px rgba(255,255,255,0.2)', '0 0 0 rgba(0,0,0,0)', '0 0 0 rgba(0,0,0,0)']);
  useEffect(() => {
    progress.set(0); 
    const controls = animate(progress, 1, { duration: 1.8, delay, ease: [0.16, 1, 0.3, 1] });
    return controls.stop;
  }, [value, progress, delay]);
  return <motion.span style={{ display: 'inline-block', textShadow }}>{formatted}</motion.span>;
});

const calculateProgress = (historyData, tBase, gddStart, gddEnd, currentYear, pollenKeys = []) => {
  let gdd = 0, reservoir = 100, started = false, finished = false, finishDay = null;
  const now = new Date(), currentDayOfYear = Math.floor((now - new Date(currentYear, 0, 0)) / 86400000);
  for (let d = 60; d <= currentDayOfYear; d++) {
    const dateStr = new Date(currentYear, 0, d).toISOString().split('T')[0];
    const dayData = historyData.find(item => item.date === dateStr);
    let temp = -3 + (d - 60) * 0.233, precip = 0, humidity = 60, wind = 3;
    if (dayData) {
      temp = dayData.tempAvg ?? ((dayData.tempMax + dayData.tempMin) / 2);
      precip = dayData.precip ?? 0; humidity = dayData.humidity ?? 60; wind = dayData.windMax ?? 3;
    }
    gdd += Math.max(temp - tBase, 0);
    let dailyPollen = pollenKeys.reduce((s, k) => s + (Number(dayData?.[k]) || 0), 0);
    if (gdd >= gddStart || dailyPollen >= 20) started = true;
    if (started && reservoir > 0) {
      if (precip <= 1.0 && humidity <= 85) {
        let baseDepletion = (Math.max(temp - tBase, 0) / (gddEnd - gddStart)) * 100;
        reservoir -= (baseDepletion || (dailyPollen >= 5 ? 1.5 : 0)) * Math.max(1, wind / 3) * (humidity < 40 ? 1.2 : 1);
        if (reservoir <= 0) { reservoir = 0; finished = true; finishDay = d; }
      }
    }
  }
  return { gdd, reservoir, started, finished, finishDay };
};

const estimateDays = (isStart, val, target, tBase, d, forecastData) => {
  let g = val, res = val, days = 0;
  while (days < 100 && (isStart ? g < target : res > 0)) {
    days++; d++;
    let temp = -3 + (d - 60) * 0.233;
    if (days <= 7 && forecastData[days - 1]?.tempAvg !== undefined) temp = forecastData[days - 1].tempAvg;
    if (isStart) g += Math.max(temp - tBase, 0);
    else res -= (Math.max(temp - tBase, 0) / (323 - 94)) * 100;
  }
  return days;
};

const getPollenStatus = (bio, weather) => {
  const { hasStarted, isFinished, reservoir } = bio;
  const precip = weather?.precip || 0;
  const windMax = weather?.windMax || 0;
  const weathercode = weather?.weathercode;
  const temp = weather?.tempAvg !== undefined ? weather.tempAvg : 10;
  const h = weather?.humidity || 50;

  if (isFinished || reservoir <= 0) return { badge: "✅ МОЖНО ВЫДЫХАТЬ", text: "Деревья отцвели.", color: "#10b981" };
  if (!hasStarted) return { badge: "🌱 ДЕРЕВЬЯ СПЯТ", text: "Воздух чист.", color: "#10b981" };

  if (precip > 0 && windMax >= 25 && (weathercode === 95 || weathercode === 96 || weathercode === 99)) {
    return { badge: "⚡ ГРОЗОВАЯ АСТМА", text: "Экстремальная угроза разрыва пыльцы. Закройте окна!", color: "var(--critical)" };
  }

  if (precip > 5.0) {
    return { badge: "🌧️ ИНТЕНСИВНОЕ ОЧИЩЕНИЕ", text: "Ливень смывает пыльцу. Воздух очищается.", color: "#64D2FF" };
  }

  if (precip > 0.1 && precip <= 5.0) {
    return { badge: "⚠️ ОСМОТИЧЕСКИЙ ШОК", text: "Мелкий дождь разрушает пыльцу на наночастицы. Риск удушья.", color: "#FF9500" };
  }

  if (h > 85) return { badge: "💧 ПАУЗА", text: "Сырость удерживает пыльцу.", color: "#38bdf8" };
  if (windMax > 5 && h < 50) return { badge: "💨 ОПАСНЫЙ ВЕТЕР", text: "Ветер разносит пыльцу.", color: "#ef4444", pulse: true };
  return { badge: "⚠️ АКТИВНОЕ ПЫЛЕНИЕ", text: "Концентрация растет.", color: "#ef4444", pulse: true };
};
const SeasonProgressWidget = React.memo(({ historyData = [], forecastData = [] }) => {
  const isMobile = useIsMobile();
  const currentYear = new Date().getFullYear(), currentDay = Math.floor((new Date() - new Date(currentYear, 0, 0)) / 86400000), latest = historyData[0];
  const { earlyData, birchData } = useMemo(() => {
    const e = calculateProgress(historyData, 0.5, 15, 90, currentYear, ['alder', 'hazel']);
    const b = calculateProgress(historyData, 4.0, 94, 323, currentYear, ['birch']);
    return {
      earlyData: { progress: e, main: !e.started ? estimateDays(true, e.gdd, 15, 0.5, currentDay, forecastData) : (!e.finished ? Math.round(estimateDays(false, e.reservoir, 0, 0.5, currentDay, forecastData) * 1.2) : 0) },
      birchData: { progress: b, main: !b.started ? estimateDays(true, b.gdd, 94, 4.0, currentDay, forecastData) : (!b.finished ? Math.round(estimateDays(false, b.reservoir, 0, 4.0, currentDay, forecastData) * 1.2) : 0) }
    };
  }, [historyData, forecastData, currentYear, currentDay]);

  const renderCard = (title, data, grad) => {
    const { progress, main } = data, isOver = progress.finished;
    const status = getPollenStatus({ hasStarted: progress.started, isFinished: progress.finished, reservoir: progress.reservoir }, latest);
    const percent = !progress.started ? Math.min(100, Math.round((progress.gdd / 94) * 100)) : Math.round(100 - progress.reservoir);
    return (
      <div className="card" style={{ padding: 0, display: 'flex', opacity: isOver ? 0.6 : 1, overflow: 'hidden', borderRadius: '24px' }}>
        <div style={{ flex: '1 1 auto', padding: '20px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
          <div>
            <div style={{ 
                display: 'flex', 
                flexDirection: isMobile ? 'column' : 'row',
                alignItems: isMobile ? 'flex-start' : 'center',
                gap: isMobile ? '4px' : '10px', 
                marginBottom: '12px' 
              }}>
              <h2 style={{ fontSize: '18px', margin: 0, fontWeight: 800, color: '#fff' }}>{title}</h2>
              <motion.div animate={status.pulse ? { opacity: [1, 0.5, 1] } : {}} transition={{ duration: 2, repeat: Infinity }} style={{ background: `${status.color}20`, border: `1.5px solid ${status.color}40`, padding: '3px 10px', borderRadius: '20px' }}>
                <span style={{ fontSize: '10px', fontWeight: 900, color: status.color, textTransform: 'uppercase', whiteSpace: 'nowrap' }}>{status.badge}</span>
              </motion.div>
            </div>
            <p style={{ fontSize: '13px', color: '#a1a1aa', borderLeft: `2.5px solid ${status.color}60`, paddingLeft: '12px', margin: 0 }}>{status.text}</p>
          </div>
          <div style={{ width: '100%', marginTop: '20px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px', fontSize: '10px', fontWeight: 800, color: '#71717a', textTransform: 'uppercase' }}>
              <span>Прогресс</span><span>{percent}%</span>
            </div>
            <div style={{ width: '100%', height: '6px', borderRadius: '10px', backgroundColor: '#27272a', overflow: 'hidden' }}>
              <motion.div initial={{ width: 0 }} animate={{ width: `${percent}%` }} transition={{ duration: 1.5 }} style={{ height: '100%', background: grad }} />
            </div>
          </div>
        </div>
        <div style={{ 
          flex: '0 0 130px', padding: '20px 10px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', 
          background: isOver ? 'rgba(255,255,255,0.05)' : `${status.color}15`, backdropFilter: 'blur(16px)', borderLeft: `1px solid ${status.color}30` 
        }}>
          <div style={{ fontSize: '10px', fontWeight: 800, color: isOver ? '#71717a' : status.color, textTransform: 'uppercase', marginBottom: '4px' }}>{isOver ? 'Статус' : (progress.started ? 'Спад через' : 'Старт через')}</div>
          <div style={{ fontSize: '64px', fontWeight: 900, lineHeight: 0.9, letterSpacing: '-4px', color: '#fff', textShadow: isOver ? 'none' : `0 0 20px ${status.color}60` }}>
            {isOver ? "—" : <AnimatedNumber value={main} padZero={true} delay={0.4} />}
          </div>
          <div style={{ fontSize: '11px', fontWeight: 800, color: '#fff', opacity: 0.4, textTransform: 'uppercase', marginTop: '4px' }}>дней</div>
        </div>
      </div>
    );
  };

  return (
    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', flexDirection: 'column', gap: 16, marginBottom: 16 }}>
      {(!earlyData.progress.finished || (currentDay - earlyData.progress.finishDay <= 7)) && renderCard("Ольха+Орешник", earlyData, 'linear-gradient(90deg, #0A84FF, #32D74B)')}
      {(!birchData.progress.finished || (currentDay - birchData.progress.finishDay <= 7)) && renderCard("Берёза", birchData, 'linear-gradient(90deg, #fbbf24, #ef4444)')}
    </motion.div>
  );
});

export default SeasonProgressWidget;