import React from 'react';
import { BarChart2 } from 'lucide-react';
import { Line, Bar } from 'react-chartjs-2';
import { ChartWithStickyAxis, chartOptionsCommon } from './ChartUtils';
import SegmentControl from './ui/SegmentControl';
import LegendPill from './ui/LegendPill';

const SeasonComparisonWidget = ({
  archiveRange, setArchiveRange,
  archivePollenChartType, setArchivePollenChartType,
  archivePollenScaleType, setArchivePollenScaleType,
  activeYears, setActiveYears,
  activeAllergens, setActiveAllergens,
  archiveChartData
}) => {
  return (
    <div className="card overflow-hidden w-full">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px', marginBottom: '15px' }}>
        <div style={{ minWidth: '200px' }}>
          <h3 className="section-title" style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
            <BarChart2 size={18} /> Сравнение сезонов
          </h3>
          <p style={{ fontSize: 11, color: 'var(--text-secondary)', margin: '4px 0 0 26px' }}>Эстафета аллергенов: Деревья</p>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
          <SegmentControl 
            options={[{label: 'Сезон', value: 'season'}, {label: 'Месяц', value: 'month'}, {label: 'Неделя', value: 'week'}]}
            activeOption={archiveRange}
            onChange={setArchiveRange}
          />

          <div style={{ margin: 0, display: 'flex', background: 'rgba(255, 255, 255, 0.08)', padding: '4px', borderRadius: '12px', gap: '4px' }}>
            <button 
              onClick={() => setArchivePollenChartType('bar')}
              title="Столбчатая диаграмма"
              style={{ padding: '6px 14px', borderRadius: '8px', border: 'none', background: archivePollenChartType === 'bar' ? 'rgba(255, 255, 255, 0.15)' : 'transparent', color: archivePollenChartType === 'bar' ? '#fff' : 'var(--text-secondary)', cursor: 'pointer', transition: '0.2s', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
            >
              <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="18" y1="20" x2="18" y2="10"></line>
                <line x1="12" y1="20" x2="12" y2="4"></line>
                <line x1="6" y1="20" x2="6" y2="14"></line>
              </svg>
            </button>
            <button 
              onClick={() => setArchivePollenChartType('line')}
              title="Линейный график"
              style={{ padding: '6px 14px', borderRadius: '8px', border: 'none', background: archivePollenChartType === 'line' ? 'rgba(255, 255, 255, 0.15)' : 'transparent', color: archivePollenChartType === 'line' ? '#fff' : 'var(--text-secondary)', cursor: 'pointer', transition: '0.2s', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
            >
              <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M3 3v18h18"></path>
                <path d="M7 16l5-5 4 4 5-5"></path>
              </svg>
            </button>
          </div>

          <SegmentControl 
            options={[{label: 'LIN', value: 'linear'}, {label: 'LOG', value: 'logarithmic'}]}
            activeOption={archivePollenScaleType}
            onChange={setArchivePollenScaleType}
          />
        </div>
      </div>
      
      <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', marginBottom: '20px', background: 'rgba(255, 255, 255, 0.02)', padding: '16px', borderRadius: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
          <span style={{ fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', minWidth: '70px' }}>Аллергены:</span>
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            {['alder', 'hazel', 'birch', 'oak'].map(alg => {
              const names = { alder: 'Ольха', hazel: 'Орешник', birch: 'Береза', oak: 'Дуб' };
              const colors = { alder: '#32D74B', hazel: '#FFD60A', birch: '#FF453A', oak: '#15803d' };
              const isActive = activeAllergens.includes(alg);
              const isSingleAllergen = activeAllergens.length === 1;
              
              return (
                <LegendPill
                  key={alg}
                  label={names[alg]}
                  color={isSingleAllergen ? '#8e8e93' : colors[alg]}
                  isActive={isActive}
                  onClick={() => setActiveAllergens(prev => prev.includes(alg) && prev.length > 1 ? prev.filter(a => a !== alg) : prev.includes(alg) ? prev : [...prev, alg])}
                />
              );
            })}
          </div>
        </div>
        
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
          <span style={{ fontSize: '12px', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', minWidth: '70px' }}>Годы:</span>
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            {['2026', '2025', '2024', '2023'].map(y => {
              const isActive = activeYears.includes(y);
              const isSingleAllergen = activeAllergens.length === 1;
              const yearColors = { '2026': '#64D2FF', '2025': '#FFD60A', '2024': '#FF8A65', '2023': '#32D74B' };
              
              return (
                <LegendPill 
                  key={y}
                  label={`${y} год`}
                  color={isSingleAllergen ? yearColors[y] : '#8e8e93'}
                  isActive={isActive}
                  onClick={() => setActiveYears(prev => prev.includes(y) && prev.length > 1 ? prev.filter(year => year !== y) : prev.includes(y) ? prev : [...prev, y])}
                />
              );
            })}
          </div>
        </div>
      </div>

      <ChartWithStickyAxis 
        leftWidth="45px"
        type={archivePollenChartType === 'bar' ? Bar : Line}
        chartData={archiveChartData}
        chartOptions={{
          ...chartOptionsCommon, 
          plugins: { ...chartOptionsCommon.plugins, tooltip: { enabled: false } },
          scales: { 
            x: { grid: { display: false }, ticks: { maxRotation: 0, autoSkip: true, maxTicksLimit: 12, color: 'rgba(255, 255, 255, 0.5)', font: { size: 10 } } }, 
            y: { 
              type: archivePollenScaleType, 
              min: archivePollenScaleType === 'logarithmic' ? 0.5 : 0, 
              grid: { color: 'rgba(255,255,255,0.05)', borderDash: [3, 3], drawBorder: false }, 
              ticks: {color: '#EBEBF599', callback: (v) => (archivePollenScaleType === 'logarithmic' ? ([1,10,100,1000,10000].includes(v) ? v : null) : v)} 
            }
          }
        }}
      />
    </div>
  );
};

export default SeasonComparisonWidget;