import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AlertTriangle, Eye, EyeOff } from 'lucide-react';
import pollenLogo from './logo512.png';

const VALID_ROLES = [
  { p: '996633', role: 'admin' },
  { p: '885522', role: 'editor' },
  { p: '774411', role: 'viewer' }
];

const LoginScreen = ({ onUnlock }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [shake, setShake] = useState(false);

  const handleLogin = (e) => {
    e.preventDefault();
    if (password.length === 0) return;
    setError('');
    setIsLoading(true);

    setTimeout(() => {
      const matchedRole = VALID_ROLES.find(r => r.p === password);
      if (matchedRole) {
        setIsSuccess(true);
        setTimeout(() => onUnlock?.(matchedRole.role), 400);
      } else {
        setError('Неверный пароль');
        setIsLoading(false);
        setShake(true);
        setTimeout(() => setShake(false), 500);
      }
    }, 600);
  };

  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', background: '#000', padding: '16px' }}>
      <AnimatePresence>
        {!isSuccess && (
          <motion.div 
            key="login-card"
            initial={{ opacity: 0, y: 20, scale: 0.95 }} 
            animate={{ opacity: 1, y: 0, scale: 1, x: shake ? [-10, 10, -10, 10, 0] : 0 }} 
            exit={{ opacity: 0, scale: 1.05, filter: 'blur(10px)' }}
            transition={{ duration: 0.3 }}
            style={{ 
              width: '100%', maxWidth: '300px', padding: '32px 24px', 
              background: '#1c1c1e', borderRadius: '32px', textAlign: 'center',
              boxShadow: '0 20px 40px rgba(0,0,0,0.4)', border: '1px solid rgba(255,255,255,0.1)'
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '20px' }}>
              <div style={{ width: '80px', height: '80px', background: 'rgba(255,255,255,0.03)', borderRadius: '22px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <img src={pollenLogo} alt="Logo" style={{ width: '65%', height: '65%', objectFit: 'contain' }} />
              </div>
            </div>

            <h1 style={{ margin: '0 0 4px 0', fontSize: '20px', fontWeight: 700, color: '#fff', letterSpacing: '-0.5px' }}>Пыльца Контроль</h1>
            <p style={{ margin: '0 0 24px 0', fontSize: '13px', color: '#8e8e93' }}>Введите пароль доступа</p>

            <form onSubmit={handleLogin}>
              <div style={{ position: 'relative', marginBottom: '16px' }}>
                <input 
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••"
                  inputMode="numeric"
                  maxLength={6}
                  style={{ 
                    width: '100%', padding: '14px 44px 14px 20px', background: 'rgba(255,255,255,0.05)', 
                    border: `1px solid ${error ? '#FF453A' : 'rgba(255,255,255,0.1)'}`, 
                    borderRadius: '16px', color: '#fff', fontSize: '22px', textAlign: 'center',
                    letterSpacing: showPassword ? '2px' : '4px', outline: 'none', transition: '0.2s'
                  }}
                  autoFocus
                />
                <button 
                  type="button" onClick={() => setShowPassword(!showPassword)}
                  style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', color: '#8e8e93', cursor: 'pointer', padding: '6px' }}
                >
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>

              {error && (
                <div style={{ color: '#FF453A', fontSize: '12px', marginBottom: '16px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '4px', background: 'rgba(255,69,58,0.1)', padding: '8px', borderRadius: '12px' }}>
                  <AlertTriangle size={14} /> {error}
                </div>
              )}

              <button 
                type="submit" disabled={isLoading || password.length === 0}
                style={{ 
                  width: '100%', padding: '14px', background: '#0a84ff', color: '#fff', 
                  border: 'none', borderRadius: '16px', fontSize: '16px', fontWeight: 600,
                  cursor: 'pointer', transition: '0.2s', opacity: (isLoading || password.length === 0) ? 0.5 : 1,
                  boxShadow: '0 4px 15px rgba(10,132,255,0.3)'
                }}
              >
                {isLoading ? 'Проверка...' : 'Войти'}
              </button>
            </form>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default LoginScreen;