import React from 'react';

const LegendPill = ({ label, color, isActive, onClick, icon, isDashed }) => {
  return (
    <button
      onClick={onClick}
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: '6px',
        padding: '6px 14px',
        borderRadius: '20px',
        cursor: 'pointer',
        fontSize: '13px',
        fontWeight: 500,
        border: isActive ? `1px solid ${color}80` : '1px solid rgba(255, 255, 255, 0.1)',
        backgroundColor: isActive ? `${color}20` : 'rgba(255, 255, 255, 0.05)',
        color: isActive ? color : 'var(--text-secondary)',
        transition: 'all 0.2s ease',
        userSelect: 'none',
        borderStyle: isDashed && !isActive ? 'dashed' : 'solid'
      }}
    >
      {icon && icon}
      {label}
    </button>
  );
};

export default LegendPill;