import React, { useState, useEffect, useRef } from 'react';
import './App.css';
// All imports for AppContent are now inside AppContent or its children
import LoginScreen from './LoginScreen';
import AddDataModal from './AddDataModal';
import Header from './components/Header';
import TabToday from './tabs/TabToday';
import TabHistory from './tabs/TabHistory';
import TabAdmin from './tabs/TabAdmin';
import ErrorBoundary from './ErrorBoundary';
import { PollenProvider, usePollenContext } from './DataProvider';
import { Chart as ChartJS, CategoryScale, LinearScale, LogarithmicScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend, Filler } from 'chart.js';
import { useIsMobile } from './hooks/useIsMobile';

ChartJS.register(
  CategoryScale, LinearScale, LogarithmicScale, 
  PointElement, LineElement, BarElement,
  Title, Tooltip, Legend, Filler
);

const AppContent = () => {
  const [locked, setLocked] = useState(true);
  const [role, setRole] = useState(null); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editData, setEditData] = useState(null);
  const [activeTab, setActiveTab] = useState(0);

  const { historyData, fetchMeasurements } = usePollenContext();
  const isMobile = useIsMobile();
  const viewsRef = useRef(null);

  useEffect(() => {
    const isAuth = localStorage.getItem('isAuth');
    const authTimestamp = localStorage.getItem('authTimestamp');
    const savedRole = localStorage.getItem('authRole');

    if (isAuth === 'true' && authTimestamp) {
      const now = Date.now();
      const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

      if (now - parseInt(authTimestamp, 10) < SEVEN_DAYS_MS) {
        setLocked(false);
        if (savedRole) setRole(savedRole);
      } else {
        localStorage.removeItem('isAuth');
        localStorage.removeItem('authTimestamp');
        localStorage.removeItem('authRole');
      }
    }
  }, []);

  useEffect(() => {
    if (!locked) {
      fetchMeasurements();
    }
  }, [locked, fetchMeasurements]);

  useEffect(() => {
    if (locked) return;

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1 });

    const timeoutId = setTimeout(() => {
      const cards = document.querySelectorAll('.card');
      cards.forEach(card => observer.observe(card));
    }, 100);

    return () => {
      clearTimeout(timeoutId);
      observer.disconnect();
    };
  }, [locked, activeTab, historyData]);

  // --- Логика перетаскивания (свайпа) мышью ---
  const isDragging = useRef(false);
  const startX = useRef(0);
  const scrollLeftRef = useRef(0);

  const handleMouseDown = (e) => {
    isDragging.current = true;
    startX.current = e.pageX - viewsRef.current.offsetLeft;
    scrollLeftRef.current = viewsRef.current.scrollLeft;
    viewsRef.current.style.scrollSnapType = 'none'; // Отключаем прилипание во время драга
    viewsRef.current.style.cursor = 'grabbing';
  };

  const handleMouseLeaveOrUp = () => {
    if (!isDragging.current) return;
    isDragging.current = false;
    if (viewsRef.current) {
      viewsRef.current.style.scrollSnapType = 'x mandatory'; // Включаем прилипание обратно
      viewsRef.current.style.cursor = '';
      const width = viewsRef.current.clientWidth;
      const maxTabIndex = role === 'admin' ? 2 : 1;
      const newTab = Math.max(0, Math.min(maxTabIndex, Math.round(viewsRef.current.scrollLeft / width)));
      switchTab(newTab); // Плавно дотягиваем до ближайшей вкладки
    }
  };

  const handleMouseMove = (e) => {
    if (!isDragging.current) return;
    e.preventDefault();
    const x = e.pageX - viewsRef.current.offsetLeft;
    const walk = (x - startX.current) * 1.5; // Скорость прокрутки мышью
    if (viewsRef.current) {
      viewsRef.current.scrollLeft = scrollLeftRef.current - walk;
    }
  };

  const handleScroll = () => {
    if (!viewsRef.current) return;
    const scrollLeft = viewsRef.current.scrollLeft;
    const width = viewsRef.current.clientWidth;
    const maxTabIndex = role === 'admin' ? 2 : 1;
    const newTab = Math.max(0, Math.min(maxTabIndex, Math.round(scrollLeft / width)));
    if (newTab !== activeTab) setActiveTab(newTab);
  };

  const switchTab = (index) => {
    setActiveTab(index);
    if (viewsRef.current) {
      viewsRef.current.scrollTo({ left: index * viewsRef.current.clientWidth, behavior: 'smooth' });
    }
  };

  return (
    <div className="app-container">
      {locked && (
        <LoginScreen 
          onUnlock={(assignedRole) => { 
            setRole(assignedRole); 
            setLocked(false); 
            localStorage.setItem('isAuth', 'true');
            localStorage.setItem('authTimestamp', Date.now().toString());
            if (assignedRole) localStorage.setItem('authRole', assignedRole);
          }} 
        />
      )}

      {!locked && (
        <AddDataModal 
          isOpen={isModalOpen}
          onClose={() => { setIsModalOpen(false); setEditData(null); }}
          editData={editData}
          onSuccess={fetchMeasurements}
          historyData={historyData}
        />
      )}

      {!locked && (
        <>
          <Header activeTab={activeTab} setActiveTab={switchTab} role={role} onAddClick={() => setIsModalOpen(true)} />

          <div 
            className="views-wrapper" 
            ref={viewsRef} 
            onScroll={handleScroll}
            onMouseDown={handleMouseDown}
            onMouseLeave={handleMouseLeaveOrUp}
            onMouseUp={handleMouseLeaveOrUp}
            onMouseMove={handleMouseMove}
            style={{ 
              alignItems: 'flex-start',
              overflowX: 'auto',
              overscrollBehaviorX: 'none', // Блокирует системный жест "Назад/Вперед" в браузере при свайпе
              scrollSnapType: 'x mandatory', // Включает нативную плавную доводку свайпа
              scrollbarWidth: 'none' // Прячет системный ползунок прокрутки
            }}
          >
            <div className="view-pane" style={{ scrollSnapAlign: 'start' }}>
               <ErrorBoundary>
                 <TabToday isMobile={isMobile} role={role} setIsModalOpen={setIsModalOpen} setEditData={setEditData} />
               </ErrorBoundary>
            </div>
            <div className="view-pane" style={{ scrollSnapAlign: 'start' }}>
               <ErrorBoundary>
                 <TabHistory isMobile={isMobile} />
               </ErrorBoundary>
            </div>
            {role === 'admin' && (
              <div className="view-pane" style={{ scrollSnapAlign: 'start' }}>
                <ErrorBoundary><TabAdmin isMobile={isMobile} /></ErrorBoundary>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default function App() {
  return (
    <PollenProvider>
      <AppContent />
    </PollenProvider>
  );
}
