import React, { useState, useEffect, useMemo, useRef } from 'react';
import { doc, setDoc, deleteDoc } from 'firebase/firestore';
import { db } from './firebase';
import { Minus, ChevronDown, AlertTriangle, Plus } from 'lucide-react';
import { AllergenIcons } from './components/ui/AllergenIcons';

const ALLERGENS = [
  { id: 'alder', label: 'Ольха', icon: AllergenIcons.alder, color: '#32D74B' },
  { id: 'hazel', label: 'Орешник', icon: AllergenIcons.hazel, color: '#FFD60A' },
  { id: 'birch', label: 'Береза', icon: AllergenIcons.birch, color: '#FF453A' },
  { id: 'oak', label: 'Дуб', icon: AllergenIcons.oak, color: '#15803d' },
  { id: 'grass', label: 'Злаки', icon: AllergenIcons.grass, color: '#a3e635' },
  { id: 'weed', label: 'Сорные травы', icon: AllergenIcons.weed, color: '#facc15' },
  { id: 'clado', label: 'Кладоспориум', icon: AllergenIcons.clado, color: '#a855f7' },
  { id: 'alt', label: 'Альтернария', icon: AllergenIcons.alt, color: '#d946ef' }
];

const AllergenInput = ({ id, label, icon: Icon, color, value, onChange, lastKnown, prevValData }) => {
  const [touched, setTouched] = useState(false);
  const wheelRef = useRef(null);

  // Функция вызова легкой вибрации (поддерживается на большинстве Android и в некоторых PWA на iOS)
  const triggerHaptic = () => {
    if (typeof navigator !== 'undefined' && navigator.vibrate) {
      navigator.vibrate(10); // 10 мс - короткий и легкий "щелчок"
    }
  };

  useEffect(() => {
    if (value !== "") setTouched(true);
  }, [value]);

  const displayValue = touched ? value : (lastKnown !== null && lastKnown !== undefined ? lastKnown : "");
  const displayValueRef = useRef(displayValue);
  useEffect(() => { displayValueRef.current = displayValue; }, [displayValue]);

  useEffect(() => {
    const el = wheelRef.current;
    if (!el) return;

    const handleNativeWheel = (e) => {
      e.preventDefault(); // Блокируем скролл страницы на ПК
      const current = displayValueRef.current === "" ? 0 : Number(displayValueRef.current);
      const delta = e.deltaY > 0 ? -1 : 1;
      const next = Math.max(0, current + delta);
      if (current !== next) {
        triggerHaptic();
      }
      onChange(next);
      setTouched(true);
    };

    let touchStartY = 0;
    const handleNativeTouchStart = (e) => {
      touchStartY = e.touches[0].clientY;
    };

    const handleNativeTouchMove = (e) => {
      e.preventDefault(); // Блокируем скролл модалки на мобилках при свайпе инпута!
      const currentY = e.touches[0].clientY;
      const diff = touchStartY - currentY;
      if (Math.abs(diff) > 15) { // Порог чувствительности свайпа
        const current = displayValueRef.current === "" ? 0 : Number(displayValueRef.current);
        const delta = diff > 0 ? 1 : -1;
        const next = Math.max(0, current + delta);
        if (current !== next) {
          triggerHaptic();
        }
        onChange(next);
        setTouched(true);
        touchStartY = currentY;
      }
    };

    el.addEventListener('wheel', handleNativeWheel, { passive: false });
    el.addEventListener('touchstart', handleNativeTouchStart, { passive: false });
    el.addEventListener('touchmove', handleNativeTouchMove, { passive: false });
    
    return () => {
      el.removeEventListener('wheel', handleNativeWheel);
      el.removeEventListener('touchstart', handleNativeTouchStart);
      el.removeEventListener('touchmove', handleNativeTouchMove);
    };
  }, [onChange]);

  const numVal = Number(displayValue);
  const isAlert = touched && displayValue !== "" && (numVal >= 500 || (prevValData > 0 && numVal >= prevValData * 10));

  return (
    <div className="allergen-inline-row" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 0', borderBottom: '1px solid var(--glass-border)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
        <div style={{ background: color, width: 36, height: 36, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', boxShadow: `0 4px 10px ${color}40` }}>
          <Icon size={20} />
        </div>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <span style={{ fontSize: 16, fontWeight: 600, color: 'var(--text-main)' }}>{label}</span>
          {prevValData !== null && prevValData !== undefined && (
            <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>Вчера: {prevValData}</span>
          )}
        </div>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        {isAlert && <AlertTriangle size={20} color="var(--critical)" />}
        <div 
          ref={wheelRef}
          className="hybrid-input-wrapper"
          style={{ position: 'relative', width: '85px', height: '44px', background: touched ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.03)', borderRadius: '14px', border: isAlert ? '1px solid var(--critical)' : (touched ? '1px solid rgba(255,255,255,0.2)' : '1px solid var(--glass-border)'), overflow: 'hidden', transition: 'all 0.3s ease', cursor: 'ns-resize' }}
        >
          <input type="number" value={displayValue} onChange={(e) => { onChange(e.target.value); setTouched(true); }} placeholder="-" style={{ width: '100%', height: '100%', background: 'transparent', border: 'none', textAlign: 'right', paddingRight: '16px', fontSize: '20px', fontWeight: 700, color: touched ? 'var(--text-main)' : 'var(--text-secondary)', outline: 'none', appearance: 'none', WebkitAppearance: 'none' }} />
        </div>
      </div>
    </div>
  );
};

const AddDataModal = ({ isOpen, onClose, editData, onSuccess, historyData = [] }) => {
  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  const [date, setDate] = useState(todayStr);
  const [values, setValues] = useState({});
  const [localCustomAllergens, setLocalCustomAllergens] = useState([]);
  const [saveError, setSaveError] = useState("");
  const [saveLoading, setSaveLoading] = useState(false);
  
  const [isWeekend, setIsWeekend] = useState(false);
  const [prevData, setPrevData] = useState(null);
  const [weather, setWeather] = useState("Загрузка...");
  const [weatherStats, setWeatherStats] = useState(null);
  const [isAccordionOpen, setIsAccordionOpen] = useState(false);

  // Динамически вычисляем все доступные аллергены (статика + история БД + свежедобавленные руками)
  const activeAllergenDefs = useMemo(() => {
    const map = new Map();
    ALLERGENS.forEach(a => map.set(a.id, a));
    
    historyData.forEach(d => {
      Object.keys(d).forEach(k => {
        if (!['date', 'tempAvg', 'tempMax', 'tempMin', 'precip', 'windMax', 'humidity', 'phenomena', 'windDir'].includes(k)) {
          if (!map.has(k)) {
            map.set(k, { id: k, label: k, icon: AllergenIcons.weed, color: '#8E8E93' });
          }
        }
      });
    });

    localCustomAllergens.forEach(a => map.set(a.id, a));
    return Array.from(map.values());
  }, [historyData, localCustomAllergens]);

  // При открытии окна сбрасываем ошибки и заполняем данные (если это редактирование)
  useEffect(() => {
    if (isOpen) {
      setSaveError("");
      setSaveLoading(false);
      setIsWeekend(false);
      setIsAccordionOpen(false);
      setWeatherStats(null);
      
      const initialValues = {};
      activeAllergenDefs.forEach(a => {
        initialValues[a.id] = "";
      });

      if (editData) {
        setDate(editData.date);
        Object.keys(editData).forEach(k => {
          if (!['date', 'tempAvg', 'tempMax', 'tempMin', 'precip', 'windMax', 'humidity', 'phenomena', 'windDir'].includes(k)) {
            if (editData[k] !== null && editData[k] !== undefined) {
              initialValues[k] = editData[k];
            }
          }
        });
      } else {
        setDate(todayStr);
      }
      setValues(initialValues);
    }
  }, [isOpen, editData, todayStr]); // Не добавляем activeAllergenDefs, чтобы не сбрасывать values при добавлении новых

  // Вычисляем последние введенные значения для "умного старта" (скрапятся из последнего дня, где они были)
  const lastKnownValues = useMemo(() => {
    const vals = {};
    activeAllergenDefs.forEach(a => {
      const lastRec = historyData.find(d => d[a.id] !== null && d[a.id] !== undefined && d[a.id] !== "");
      vals[a.id] = lastRec ? lastRec[a.id] : null;
    });
    return vals;
  }, [historyData, activeAllergenDefs]);

  // Поиск предыдущих значений для валидации и бэйджей
  useEffect(() => {
    if (isOpen && historyData.length > 0 && date) {
      // Строго используем UTC, чтобы избежать багов со смещением в разных часовых поясах
      const targetDate = new Date(date + 'T00:00:00Z');
      targetDate.setUTCDate(targetDate.getUTCDate() - 1);
      const prevDateStr = targetDate.toISOString().split('T')[0];
      const found = historyData.find(d => d.date === prevDateStr);
      setPrevData(found || null);
    } else {
      setPrevData(null);
    }
  }, [isOpen, date, historyData]);

  // Запрос погоды (open-meteo API)
  useEffect(() => {
    if (isOpen && date) {
      setWeather("Загрузка...");
      const fetchW = async () => {
        try {
          const today = new Date();
          const target = new Date(date);
          const diffDays = (today - target) / (1000 * 60 * 60 * 24);
          // Open-Meteo требует использования archive API для старых дат (>60 дней)
          const baseUrl = diffDays > 60 ? 'https://archive-api.open-meteo.com/v1/archive' : 'https://api.open-meteo.com/v1/forecast';
          
          const url = `${baseUrl}?latitude=55.75&longitude=37.62&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,windspeed_10m_max&hourly=relative_humidity_2m&timezone=Europe%2FMoscow&start_date=${date}&end_date=${date}&windspeed_unit=ms`;
          const res = await fetch(url);
          const wData = await res.json();
          if (wData?.daily?.temperature_2m_max?.length > 0 && wData.daily.temperature_2m_max[0] !== null) {
            const tempMax = wData.daily.temperature_2m_max[0];
            const tempMin = wData.daily.temperature_2m_min[0];
            const precip = wData.daily.precipitation_sum[0] || 0;
            const wind = wData.daily.windspeed_10m_max[0] || 0;
            
            const humArr = wData.hourly?.relative_humidity_2m || [];
            const humidity = humArr.length > 0 ? Math.round(humArr.reduce((a,b) => a + b, 0) / humArr.length) : null;
            const tempAvg = Math.round((tempMax + tempMin) / 2);

            setWeather(`${tempMax > 0 ? '+' : ''}${Math.round(tempMax)}°C${precip > 0 ? ', осадки: ' + precip + 'мм' : ''}`);
            setWeatherStats({ tempAvg, tempMax, tempMin, precip, windMax: Math.round(wind), humidity });
          } else {
            setWeather("Нет данных");
            setWeatherStats(null);
          }
        } catch(e) {
          setWeather("Ошибка API");
          setWeatherStats(null);
        }
      };
      fetchW();
    }
  }, [isOpen, date]);

  const handleValueChange = (id, val) => {
    setValues(prev => ({ ...prev, [id]: val }));
  };

  const handleWeekendToggle = (e) => {
    setIsWeekend(e.target.checked);
  };

  const handleSave = async () => {
    setSaveError("");
    setSaveLoading(true);

    if (!isWeekend && Object.values(values).every(val => val === "")) {
      setSaveError("Введите хотя бы одно значение или отметьте 'Нет замеров'!");
      setSaveLoading(false);
      return;
    }

    try {
      const dataObj = { date };

      if (isWeekend) {
        activeAllergenDefs.forEach(a => { dataObj[a.id] = null; });
      } else {
        activeAllergenDefs.forEach(a => {
          const value = values[a.id];
          // Если значение пустое - значит не трогали, передаем null (очищаем/пропускаем)
          dataObj[a.id] = (value === "" || value === undefined) ? null : Number(value);
        });
      }

      // Если это новое сохранение (не редактирование) и есть данные погоды, добавляем их
      if (!editData && weatherStats) {
        dataObj.tempAvg = weatherStats.tempAvg;
        dataObj.tempMax = weatherStats.tempMax;
        dataObj.tempMin = weatherStats.tempMin;
        dataObj.precip = weatherStats.precip;
        dataObj.windMax = weatherStats.windMax;
        dataObj.humidity = weatherStats.humidity;
      }

      // Предотвращаем отправку пустой даты без погоды и без метки выходного
      if (Object.keys(dataObj).length === 1 && !isWeekend) {
        onClose(); 
        return;
      }

      await setDoc(doc(db, 'measurements', date), dataObj, { merge: true });
      onSuccess();
      onClose();
    } catch (e) {
      setSaveError("Ошибка сохранения: " + (e.message || e));
      setSaveLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm("Вы уверены, что хотите удалить данные за этот день? Это действие необратимо.")) return;
    setSaveLoading(true);
    try {
      await deleteDoc(doc(db, 'measurements', date));
      onSuccess();
      onClose();
    } catch (e) {
      setSaveError("Ошибка удаления: " + (e.message || e));
      setSaveLoading(false);
    }
  };

  // Динамическая сортировка (Правило 3 дней + Режим редактирования)
  const { activeAllergens, archiveAllergens } = useMemo(() => {
    if (editData) {
      const active = [];
      const archive = [];
      activeAllergenDefs.forEach(a => {
        if (editData[a.id] !== null && editData[a.id] !== undefined && editData[a.id] !== "") active.push(a);
        else archive.push(a);
      });
      return { activeAllergens: active.sort((a,b) => editData[b.id] - editData[a.id]), archiveAllergens: archive };
    }
    
    const targetTime = new Date(date + 'T00:00:00Z').getTime();
    const last3 = historyData.filter(d => new Date(d.date + 'T00:00:00Z').getTime() < targetTime).slice(0, 3);

    const activeSet = new Set();
    last3.forEach(d => {
      ALLERGENS.forEach(a => { if (d[a.id] > 0) activeSet.add(a.id); });
    });
    
    // Реактивность: если юзер сейчас ввел цифру > 0, аллерген сразу становится активным
    ALLERGENS.forEach(a => { if (Number(values[a.id]) > 0) activeSet.add(a.id); });

    const active = [];
    const archive = [];
    ALLERGENS.forEach(a => {
      if (activeSet.has(a.id)) active.push(a);
      else archive.push(a);
    });

    // Если нет активных за последние 3 дня (например, начало сезона), берем парочку по умолчанию
    if (active.length === 0 && archive.length > 0) {
      active.push(archive.shift()); active.push(archive.shift());
    }

    return { activeAllergens: active, archiveAllergens: archive };
  }, [date, editData, historyData, values]);

  if (!isOpen) return null;

  const renderInput = (item) => {
    return (
      <AllergenInput
        key={item.id} id={item.id} label={item.label} icon={item.icon} color={item.color}
        value={values[item.id]} onChange={(val) => handleValueChange(item.id, val)}
        lastKnown={lastKnownValues[item.id]} prevValData={prevData ? prevData[item.id] : null}
      />
    );
  };

  return (
    <div className="login-overlay" style={{ zIndex: 9998 }}>
      <div className="login-card" style={{ maxHeight: '90vh', overflowY: 'auto' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <h3 style={{ margin: 0, fontSize: 18 }}>
            {editData ? 'Редактирование данных' : 'Внесение данных'}
          </h3>
          <button style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-main)' }} onClick={onClose} aria-label="close-modal">
            <Minus size={24} />
          </button>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 15, paddingBottom: 15, borderBottom: '1px solid var(--glass-border)' }}>
            <label style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', margin: 0 }}>
              <span style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-secondary)' }}>Дата сбора:</span>
              <input type="date" className="data-input" value={date} onChange={e => setDate(e.target.value)} disabled={!!editData} style={{ width: 'auto', padding: '6px 12px', margin: 0, minHeight: 35 }} />
            </label>
            {!editData && (
              <>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: 13, color: 'var(--text-secondary)' }}>Погода (сбор):</span>
                <span style={{ fontSize: 13, fontWeight: 500, color: 'var(--text-secondary)' }}>{weather}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-secondary)' }}>Нет замеров (выходной)</span>
                <label className="toggle-switch">
                  <input type="checkbox" checked={isWeekend} onChange={handleWeekendToggle} />
                  <span className="slider"></span>
                </label>
              </div>
              </>
            )}
          </div>

          <div style={{ opacity: isWeekend ? 0.4 : 1, pointerEvents: isWeekend ? 'none' : 'auto', transition: '0.3s' }}>
            <div id="active-allergens-container">
              {activeAllergens.map(renderInput)}
            </div>
            {archiveAllergens.length > 0 && (
              <div className="season-accordion" style={{ marginTop: 15 }}>
                <div className="season-header" onClick={() => setIsAccordionOpen(!isAccordionOpen)}>
                  <span>{editData ? 'Остальные' : 'Остальные (неактивные)'}</span>
                  <ChevronDown size={18} style={{ transform: isAccordionOpen ? 'rotate(180deg)' : 'none', transition: '0.3s' }} />
                </div>
                <div className={`season-content ${isAccordionOpen ? 'open' : ''}`}>
                  {archiveAllergens.map(renderInput)}
                  
                  <button
                    onClick={() => {
                       const name = window.prompt("Введите название нового аллергена (например: Полынь):");
                       if (name && name.trim() !== "") {
                          const id = name.trim();
                          setLocalCustomAllergens(prev => prev.find(a => a.id === id) ? prev : [...prev, { id, label: id, icon: AllergenIcons.weed, color: '#8E8E93' }]);
                          handleValueChange(id, "");
                          setIsAccordionOpen(true);
                       }
                    }}
                    style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '12px 0', color: 'var(--accent)', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 600, fontSize: '15px', width: '100%', marginTop: '10px' }}
                  >
                    <Plus size={20} /> Добавить другой аллерген
                  </button>
                </div>
              </div>
            )}
          </div>

          {saveError && <div className="error-text show" style={{ marginTop: 10 }}>{saveError}</div>}
          
          {editData ? (
            <div style={{ display: 'flex', gap: '12px', marginTop: 15 }}>
              <button className="login-btn" style={{ flex: 1 }} onClick={handleSave} disabled={saveLoading}>{saveLoading ? '...' : 'Сохранить'}</button>
              <button className="login-btn" style={{ flex: 1, background: 'var(--critical)' }} onClick={handleDelete} disabled={saveLoading}>Удалить</button>
            </div>
          ) : (
            <button className="login-btn" style={{ marginTop: 15 }} onClick={handleSave} disabled={saveLoading}>{saveLoading ? 'Сохранение...' : 'Сохранить данные'}</button>
          )}
        </div>
      </div>
    </div>
  );
};

export default AddDataModal;