import { useMemo, useCallback } from 'react';
import ultraDb from '../weather_final_ultra.json';

export const xAxisTicksConfig = {
  maxRotation: 0,
  autoSkip: true,
  maxTicksLimit: 12,
  color: 'rgba(235, 235, 245, 0.45)',
  font: { size: 10, weight: 600 },
  padding: 10
};

export const YEAR_COLORS = {
  '2026': '#64D2FF',
  '2025': '#FFD60A',
  '2024': '#FF8A65',
  '2023': '#32D74B'
};

export const getWindDescription = (speed) => {
  if (speed == null) return '';
  if (speed < 2) return 'Штиль';
  if (speed < 5) return 'Слабый';
  if (speed < 10) return 'Умеренный';
  if (speed < 15) return 'Сильный';
  return 'Шторм';
};

export const hexToRgba = (hex, alpha) => {
  if (!hex || typeof hex !== 'string') return `rgba(255, 255, 255, ${alpha})`;
  if (hex.startsWith('rgba')) return hex;
  let cleanHex = hex.replace('#', '');
  if (cleanHex.length === 3) cleanHex = cleanHex.split('').map(c => c + c).join('');
  const r = parseInt(cleanHex.substring(0, 2), 16) || 255;
  const g = parseInt(cleanHex.substring(2, 4), 16) || 255;
  const b = parseInt(cleanHex.substring(4, 6), 16) || 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
};

export function useWeatherChartData({
  weatherData2023 = {},
  weatherData2024 = {},
  weatherData2025 = {},
  weatherData2026 = {},
  historyData = [],
  weatherScaleType = 'linear',
  weatherVis = {}
}) {
  const ultraMap = useMemo(() => {
    const map = new Map();
    if (Array.isArray(ultraDb)) {
      ultraDb.forEach(d => { if (d && d.date) map.set(d.date, d); });
    }
    return map;
  }, []);

  const historyMap = useMemo(() => {
    const map = new Map();
    if (Array.isArray(historyData)) {
      historyData.forEach(d => { if (d && d.date) map.set(d.date, d); });
    }
    return map;
  }, [historyData]);

  const { fullKeys, fullLabels } = useMemo(() => {
    const keys = [], labels = [];
    const months = [
      { m: 3, name: 'Мар', days: 31 }, { m: 4, name: 'Апр', days: 30 },
      { m: 5, name: 'Мая', days: 31 }, { m: 6, name: 'Июн', days: 30 },
      { m: 7, name: 'Июл', days: 31 }, { m: 8, name: 'Авг', days: 31 }, { m: 9, name: 'Сен', days: 30 }
    ];
    months.forEach(month => {
      for (let d = 1; d <= month.days; d++) {
        keys.push(`${String(month.m).padStart(2, '0')}-${String(d).padStart(2, '0')}`);
        labels.push(`${d} ${month.name}`);
      }
    });
    return { fullKeys: keys, fullLabels: labels };
  }, []);

  const getDayWeather = useCallback((year, dStr) => {
    const fullDate = `${year}-${dStr}`;
    const ultraData = ultraMap.get(fullDate) || {};
    const archives = { '2023': weatherData2023, '2024': weatherData2024, '2025': weatherData2025, '2026': weatherData2026 };
    const staticData = archives[year]?.[dStr] || {};
    const dbData = historyMap.get(fullDate);

    const merged = { ...staticData, ...ultraData };
    if (dbData) {
      Object.keys(dbData).forEach(key => {
        if (dbData[key] !== null && dbData[key] !== undefined && dbData[key] !== '') merged[key] = dbData[key];
      });
    }
    
    merged.compTemp = merged.tempMax ?? merged.tempAvg ?? merged.temp ?? merged.t;
    merged.compWind = merged.windMax ?? merged.windSpeedMax ?? merged.wind;
    
    return Object.keys(merged).length > 0 ? merged : null;
  }, [historyMap, ultraMap, weatherData2023, weatherData2024, weatherData2025, weatherData2026]);

  const weatherArchiveChartData = useMemo(() => {
    const cleanNum = (val) => {
      if (val === null || val === undefined || val === '') return null;
      const num = Number(val);
      return (weatherScaleType === 'logarithmic' && num < 0.1) ? null : (isNaN(num) ? null : num);
    };

    const datasets = [];
    ['2023', '2024', '2025', '2026'].forEach(year => {
      const color = YEAR_COLORS[year];
      const dataPoints = fullKeys.map(k => getDayWeather(year, k));

      datasets.push({
        type: 'line', label: `Температура (${year})`, 
        data: dataPoints.map(w => cleanNum(w?.compTemp)),
        borderColor: color, backgroundColor: 'transparent', borderWidth: year === '2026' ? 3 : 2, 
        tension: 0.4, pointRadius: 1, pointHoverRadius: 6, yAxisID: 'yTemp', 
        hidden: !weatherVis.temp || !weatherVis[year], spanGaps: true
      });
      datasets.push({
        type: 'line', label: `Влажность (${year})`, 
        data: dataPoints.map(w => cleanNum(w?.humidityMin || w?.humidity)),
        borderColor: hexToRgba(color, 0.6), borderWidth: 1, borderDash: [3, 3], 
        pointRadius: 0, yAxisID: 'yHumidity', 
        hidden: !weatherVis.humidity || !weatherVis[year], spanGaps: true
      });
      datasets.push({
        type: 'bar', label: `Осадки (${year})`, 
        data: dataPoints.map(w => cleanNum(w?.precip)),
        backgroundColor: hexToRgba(color, 0.15), borderColor: hexToRgba(color, 0.8), 
        borderWidth: 1, borderRadius: 4, yAxisID: 'yPrecip', 
        hidden: !weatherVis.precip || !weatherVis[year]
      });
    });
    return { labels: fullLabels, datasets };
  }, [fullLabels, fullKeys, weatherScaleType, weatherVis, getDayWeather]);

  const weatherChartOptions = useMemo(() => ({
    responsive: true, maintainAspectRatio: false,
    interaction: { mode: 'index', intersect: false },
    layout: { padding: { left: 10, right: 10, top: 15, bottom: 0 } },
    plugins: {
      legend: { display: false },
      tooltip: {
        backgroundColor: 'rgba(28, 28, 30, 0.95)',
        callbacks: {
          afterBody: (context) => {
            const [day, mon] = context[0].label.split(' ');
            const monthMap = {'Мар':'03', 'Апр':'04', 'Мая':'05', 'Июн':'06', 'Июл':'07', 'Авг':'08', 'Сен':'09'};
            const key = `${monthMap[mon]}-${day.padStart(2, '0')}`;
            let lines = [];
            ['2026', '2025', '2024', '2023'].forEach(year => {
              if (!weatherVis[year]) return;
              const w = getDayWeather(year, key);
              if (!w) return;
              const t = w.compTemp;
              lines.push(`${year}:  🌡️ ${t > 0 ? '+' : ''}${t ?? '--'}°  💧 ${w.precip ?? 0}мм`);
              if (w.humidityMin) lines.push(`   └ 💦 Мин. влажность: ${w.humidityMin}%`);
              if (w.compWind) lines.push(`   └ 🌬️ ${w.compWind} м/с (${getWindDescription(w.compWind)})${w.windDir ? ' 🧭 '+w.windDir : ''}`);
              if (w.phenomena?.length) lines.push(`   └ ⚠️ ${w.phenomena.join(', ')}`);
            });
            return lines;
          }
        }
      }
    },
    scales: {
      x: { grid: { display: false }, ticks: xAxisTicksConfig, min: fullLabels[0], max: fullLabels[fullLabels.length - 1] },
      yTemp: { display: true, position: 'left', suggestedMin: -10, suggestedMax: 30, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: 'rgba(235, 235, 245, 0.6)', callback: v => v + '°'} },
      yPrecip: { display: false, type: weatherScaleType, min: weatherScaleType === 'logarithmic' ? 0.1 : 0, max: 150 },
      yHumidity: { display: true, position: 'right', min: 0, max: 100, grid: { display: false }, ticks: { color: '#64D2FF', font: {size: 10}, callback: v => v + '%' } }
    }
  }), [weatherScaleType, weatherVis, getDayWeather, fullLabels]);

  return { weatherArchiveChartData, weatherChartOptions };
}