import React, { useMemo } from 'react';
import { Calendar } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { getHeatmapColor, getHeatmapBoxShadow } from './ChartUtils';

const PollenHeatmapWidget = ({ activeAllergens, activeYears, archiveLabels, archiveChartData, isMobile }) => {
  const { trimmedLabels, trimmedDatasets } = useMemo(() => {
    if (!archiveLabels || !archiveChartData || !archiveChartData.datasets) {
      return { trimmedLabels: [], trimmedDatasets: [] };
    }

    let firstIndex = -1;
    let lastIndex = -1;
    const numPoints = archiveLabels.length;

    for (let i = 0; i < numPoints; i++) {
      let hasData = false;
      for (const ds of archiveChartData.datasets) {
        if (ds.data[i] !== null && ds.data[i] > 0) {
          hasData = true;
          break;
        }
      }
      if (hasData) {
        if (firstIndex === -1) firstIndex = i;
        lastIndex = i;
      }
    }

    if (firstIndex === -1) {
      firstIndex = 0;
      lastIndex = Math.max(0, numPoints - 1);
    }

    const padding = 3;
    firstIndex = Math.max(0, firstIndex - padding);
    lastIndex = Math.min(numPoints - 1, lastIndex + padding);

    const tLabels = archiveLabels.slice(firstIndex, lastIndex + 1);
    const tDatasets = archiveChartData.datasets.map(ds => ({
      ...ds,
      data: ds.data.slice(firstIndex, lastIndex + 1)
    }));

    return { trimmedLabels: tLabels, trimmedDatasets: tDatasets };
  }, [archiveLabels, archiveChartData]);

  const formatLabel = (lbl) => {
    if (!lbl) return '';
    if (lbl.includes('.')) {
      const parts = lbl.split('.');
      if (parts.length >= 2) {
        const day = parseInt(parts[0], 10);
        const monthIndex = parseInt(parts[1], 10) - 1;
        const months = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
        if (monthIndex >= 0 && monthIndex < 12) {
          return `${day} ${months[monthIndex]}`;
        }
      }
    }
    if (lbl.includes('-')) {
      const d = new Date(lbl);
      if (!isNaN(d)) {
        return d.toLocaleDateString('ru-RU', { day: 'numeric', month: 'short' }).replace(' г.', '');
      }
    }
    return lbl;
  };

  return (
    <div className="card overflow-hidden w-full">
      <h3 className="section-title"><Calendar size={18} /> Тепловая карта пыления</h3>
      <p style={{ fontSize: 11, color: 'var(--text-secondary)', marginBottom: 15 }}>
        Интенсивность выбросов по дням (светлее — низкая, ярче — экстремальная).
      </p>
      
      {activeAllergens.length === 0 || activeYears.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px 20px', color: 'var(--text-secondary)', fontSize: 14 }}>
          Выберите хотя бы один аллерген и год для отображения тепловой карты.
        </div>
      ) : isMobile ? (
        <div className="heatmap-mobile custom-scrollbar" style={{ overflowY: 'auto', maxHeight: '60vh', paddingRight: 5 }}>
          <div className="flex md:hidden mb-2 w-full pl-[52px] pr-2" style={{ position: 'sticky', top: 0, zIndex: 10, background: 'rgba(28, 28, 30, 0.95)', backdropFilter: 'blur(4px)', WebkitBackdropFilter: 'blur(4px)', paddingLeft: '52px', paddingTop: '8px', paddingBottom: '8px', display: 'flex', width: '100%' }}>
            <div style={{ display: 'grid', gridTemplateColumns: `repeat(${activeAllergens.length}, minmax(0, 1fr))`, width: '100%', gap: '4px' }}>
              {activeAllergens.map(alg => {
                const names = { alder: 'Ольха', hazel: 'Орешник', birch: 'Берёза', oak: 'Дуб' };
                const colors = { alder: '#4ade80', hazel: '#eab308', birch: '#ef4444', oak: '#15803d' };
                return (
                  <div key={alg} className="flex flex-col items-center overflow-hidden" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', overflow: 'hidden' }}>
                    <span className="text-[8px] sm:text-[9px] font-black uppercase tracking-tighter mb-0.5" style={{ color: colors[alg], fontSize: '9px', fontWeight: 900, textTransform: 'uppercase', letterSpacing: '-0.05em', marginBottom: '2px' }}>{names[alg]}</span>
                    <div className="flex justify-between w-full px-0.5" style={{ display: 'flex', justifyContent: 'space-between', width: '100%', padding: '0 2px' }}>
                      {activeYears.map(y => (
                        <span key={y} className="text-[7px] sm:text-[8px]" style={{ color: y === '2026' ? '#fff' : '#6b7280', fontWeight: y === '2026' ? 'bold' : 'normal', fontSize: '8px' }}>{y.slice(-2)}</span>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            {trimmedLabels.map((lbl, i) => (
              <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <div style={{ width: 47, fontSize: 10, color: 'var(--text-secondary)', textAlign: 'right', flexShrink: 0 }}>
                  {formatLabel(lbl)}
                </div>
                <div style={{ display: 'flex', gap: 4, flex: 1 }}>
                  <AnimatePresence>
                  {trimmedDatasets.map((ds, dsIndex) => {
                    const val = ds.data[i];
                    const baseColor = ds.borderColor && ds.borderColor.startsWith('#') 
                      ? ds.borderColor.substring(0, 7) 
                      : 'var(--accent)';
                    let opacity = 0.02;
                    if (val > 0) {
                      if (val < 10) opacity = 0.3;
                      else if (val < 100) opacity = 0.6;
                      else if (val < 500) opacity = 0.85;
                      else opacity = 1;
                    }
                    return (
                      <motion.div 
                        key={ds.label} 
                        layout
                        initial={{ opacity: 0, scale: 0.3, width: 0, marginRight: -4 }}
                        animate={{ opacity: val > 0 ? opacity : 1, scale: 1, width: 14, marginRight: 0 }}
                        exit={{ opacity: 0, scale: 0.3, width: 0, marginRight: -4 }}
                        transition={{ duration: 0.3, delay: (i * 0.015) + (dsIndex * 0.015) }}
                        title={`${ds.label} | ${formatLabel(lbl)}: ${val !== null ? val : 0} ед/м³`}
                        style={{
                          flex: 1, minWidth: 4, height: 14, borderRadius: 3,
                          backgroundColor: val > 0 ? baseColor : 'rgba(255,255,255,0.02)',
                          boxShadow: val > 10 ? `0 0 ${opacity * 12}px ${baseColor}` : 'none'
                        }} 
                      />
                    );
                  })}
                  </AnimatePresence>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
      <div className="heatmap-wrapper custom-scrollbar" style={{ overflowX: 'auto', paddingBottom: 15 }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6, minWidth: 'max-content' }}>
          <AnimatePresence>
          {trimmedDatasets.map((ds, index, arr) => {
            const currentBaseName = ds.label.split(' ')[0];
            const prevBaseName = index > 0 ? arr[index - 1].label.split(' ')[0] : currentBaseName;
            const isNewGroup = currentBaseName !== prevBaseName;

            return (
              <motion.div 
                key={ds.label} 
                layout
                initial={{ opacity: 0, height: 0, marginTop: 0, marginBottom: -6 }}
                animate={{ opacity: 1, height: 14, marginTop: isNewGroup ? 16 : 0, marginBottom: 0, transitionEnd: { overflow: 'visible' } }}
                exit={{ opacity: 0, height: 0, marginTop: 0, marginBottom: -6, overflow: 'hidden' }}
                style={{ display: 'flex', alignItems: 'center', overflow: 'hidden' }}
              >
                <div style={{ width: 108, flexShrink: 0, paddingRight: 8, position: 'sticky', left: 0, zIndex: 2, background: 'rgba(28, 28, 30, 0.95)', backdropFilter: 'blur(4px)', WebkitBackdropFilter: 'blur(4px)', fontSize: 11, fontWeight: 600, color: 'var(--text-secondary)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {ds.label}
                </div>
                <div style={{ display: 'flex', gap: 4 }}>
                  {ds.data.map((value, i) => {
                    return (
                      <motion.div 
                        key={i} 
                        initial={{ opacity: 0, scale: 0.3 }}
                        animate={{ opacity: 1, scale: 1 }}
                        transition={{ duration: 0.3, delay: (i * 0.015) + (index * 0.015) }}
                        whileHover={{ scale: 1.2 }}
                        title={`${ds.label} | ${formatLabel(trimmedLabels[i])}: ${value !== null ? value : 0} ед/м³`}
                        style={{
                          width: 14, height: 14, borderRadius: 3, flexShrink: 0,
                          backgroundColor: getHeatmapColor(value),
                          boxShadow: getHeatmapBoxShadow(value),
                          cursor: 'crosshair'
                        }} 
                      />
                    );
                  })}
                </div>
              </motion.div>
            );
          })}
          </AnimatePresence>
          
          <div style={{ display: 'flex', alignItems: 'center', marginTop: 4 }}>
            <div style={{ width: 108, flexShrink: 0, position: 'sticky', left: 0, zIndex: 2, background: 'rgba(28, 28, 30, 0.95)', backdropFilter: 'blur(4px)', WebkitBackdropFilter: 'blur(4px)' }}>&nbsp;</div>
            <div style={{ display: 'flex', gap: 4 }}>
              {trimmedLabels.map((lbl, i) => (
                <div key={i} style={{ width: 14, flexShrink: 0, position: 'relative' }}>
                  {i % 4 === 0 && (
                    <span style={{ position: 'absolute', top: 0, left: 0, fontSize: 9, color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>
                      {formatLabel(lbl)}
                    </span>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
      )}
    </div>
  );
};

export default PollenHeatmapWidget;