import React, { useId } from 'react';
import { motion } from 'framer-motion';

const SegmentControl = ({ options, activeOption, onChange, style }) => {
  const segmentControlId = useId(); // Уникальный ID для layoutId

  return (
    <div style={{
      display: 'inline-flex',
      alignItems: 'center',
      background: 'rgba(255, 255, 255, 0.08)',
      padding: '4px',
      borderRadius: '12px',
      gap: '4px',
      ...style
    }}>
      {options.map((option) => {
        const value = option.value !== undefined ? option.value : option;
        const label = option.label !== undefined ? option.label : option;
        const active = activeOption === value;
        
        return (
          <div
            key={value}
            onClick={() => onChange(value)}
            style={{
              position: 'relative', // ОБЯЗАТЕЛЬНО!
              zIndex: 1,
              padding: '6px 14px',
              fontSize: '13px',
              fontWeight: 600,
              color: active ? '#ffffff' : 'var(--text-secondary)',
              cursor: 'pointer',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              userSelect: 'none',
              transition: 'color 0.2s ease'
            }}
          >
            {active && (
              <motion.div
                layoutId={segmentControlId}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  backgroundColor: 'rgba(255, 255, 255, 0.15)',
                  borderRadius: '8px',
                  zIndex: -1
                }}
                transition={{ type: 'spring', stiffness: 400, damping: 30 }}
              />
            )}
            {label}
          </div>
        );
      })}
    </div>
  );
};

export default SegmentControl;