import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import { History, Check } from 'lucide-react';
import { useIsMobile } from '../hooks/useIsMobile';

const DayInHistoryWidget = ({ historyData }) => {
  const isMobile = useIsMobile();
  const [isCopied, setIsCopied] = useState(false);

  // Формируем чистую выборку
  const maxDay = useMemo(() => {
    if (!historyData || historyData.length === 0) return null;

    const now = new Date();
    const offset = now.getTimezoneOffset() * 60000;
    const todayStr = new Date(now - offset).toISOString().split('T')[0];
    const currentYear = todayStr.substring(0, 4);
    const monthDay = todayStr.substring(4); // "-05-04"

    // Достаем все исторические записи за это число
    const historicalDaysRaw = historyData.filter(d => 
      d.date.endsWith(monthDay) && !d.date.startsWith(currentYear)
    );

    // Очищаем от мусора и погодных "пустышек"
    const processedDays = historicalDaysRaw.map(d => {
      const pollenKeys = ['alder', 'hazel', 'birch', 'oak', 'grass', 'weed', 'clado', 'alt'];
      
      // ЖЕСТКИЙ ФИЛЬТР: Считаем только те дни, где есть реальный замер больше нуля
      const hasPositiveData = pollenKeys.some(key => 
        d[key] !== null && d[key] !== undefined && Number(d[key]) > 0
      );

      // Если пыльцы не было (или не измеряли) - отбрасываем этот день
      if (!hasPositiveData) return null;

      const total = pollenKeys.reduce((sum, key) => sum + (Number(d[key]) || 0), 0);

      return {
        ...d,
        year: d.date.substring(0, 4),
        total: total,
        tempAvg: d.tempAvg !== undefined ? Math.round(d.tempAvg) : 
                 (d.tempMax !== undefined && d.tempMin !== undefined ? Math.round((d.tempMax + d.tempMin) / 2) : null)
      };
    }).filter(d => d !== null);

    // Если после фильтрации ничего не осталось - возвращаем null (виджет скроется)
    if (processedDays.length === 0) return null;

    // Находим худший год из оставшихся
    return processedDays.reduce((prev, current) => (prev.total > current.total) ? prev : current);
  }, [historyData]);

  // Если нет данных - ничего не рисуем
  if (!maxDay) return null;

  const isHighRisk = maxDay.total >= 50;
  const accentColor = isHighRisk ? '#FF9500' : '#34C759';

  const handleCopy = () => {
    const text = `В этот день в ${maxDay.year} году концентрация пыльцы составила ${maxDay.total} ед.`;
    navigator.clipboard.writeText(text);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  return (
    <motion.div
      onClick={handleCopy}
      whileTap={{ scale: 0.98 }}
      initial={{ opacity: 0, y: 15 }}
      animate={{ opacity: 1, y: 0 }}
      style={{
        display: 'flex', gap: '16px', alignItems: 'center',
        background: isHighRisk ? 'rgba(255, 149, 0, 0.08)' : 'rgba(255, 255, 255, 0.04)',
        borderRadius: isMobile ? '16px' : '20px',
        padding: '16px',
        borderLeft: `4px solid ${accentColor}`,
        boxShadow: '0 4px 15px rgba(0,0,0,0.1)',
        cursor: 'pointer',
        marginBottom: '20px'
      }}
    >
      <div style={{ background: 'rgba(255,255,255,0.1)', padding: '10px', borderRadius: '12px' }}>
        {isCopied ? <Check size={24} color="#34C759" /> : <History size={24} color={accentColor} />}
      </div>
      <div>
        <div style={{ fontSize: '14px', fontWeight: 'bold', color: 'var(--text-primary)', marginBottom: '4px' }}>
          В этот день в {maxDay.year} году
        </div>
        <div style={{ fontSize: '13px', color: 'var(--text-secondary)', lineHeight: '1.4' }}>
          Концентрация аллергенов достигала <span style={{ fontWeight: 'bold', color: accentColor }}>{maxDay.total} ед.</span>
          {maxDay.tempAvg !== null && ` Погода: ${maxDay.tempAvg}°C.`}
        </div>
      </div>
    </motion.div>
  );
};

export default DayInHistoryWidget;