import React from 'react';
import { AllergenIcons } from './ui/AllergenIcons';

export const formatMonth = (m) => {
  const months = {'01':'Янв', '02':'Фев', '03': 'Мар', '04': 'Апр', '05': 'Мая', '06': 'Июн', '07': 'Июл', '08': 'Авг', '09': 'Сен', '10': 'Окт', '11':'Ноя', '12':'Дек'};
  return months[m] || m;
};

export const getHeatmapColor = (value) => {
  if (value === null || value === undefined || value <= 0) return 'rgba(255,255,255,0.02)';
  if (value < 10) return 'rgba(50, 215, 75, 0.3)';
  if (value < 100) return 'rgba(255, 214, 10, 0.6)';
  if (value < 500) return 'rgba(255, 159, 10, 0.85)';
  return 'rgba(255, 69, 58, 1)';
};

export const getHeatmapBoxShadow = (value) => {
  if (value > 10) {
    let color;
    if (value < 100) color = 'rgba(255, 214, 10, 0.5)';
    else if (value < 500) color = 'rgba(255, 159, 10, 0.7)';
    else color = 'rgba(255, 69, 58, 0.8)';
    const opacity = Math.min(1, value / 1000);
    return `0 0 ${opacity * 12}px ${color}`;
  }
  return 'none';
};

export const CustomLegend = ({ datasets, hiddenState, toggleFn, isArchive }) => {
  let groups = {};
  if (isArchive) {
    datasets.forEach(ds => {
      const baseName = ds.label.split(' ')[0];
      if (!groups[baseName]) groups[baseName] = [];
      groups[baseName].push(ds);
    });
  } else {
    groups['Деревья'] = datasets;
  }

  const groupOrder = ['Береза', 'Ольха', 'Орешник', 'Деревья'];
  
  const getIconForAllergen = (label) => {
    if (label.includes('Ольха')) return AllergenIcons.alder;
    if (label.includes('Орешник')) return AllergenIcons.hazel;
    if (label.includes('Береза')) return AllergenIcons.birch;
    if (label.includes('Дуб')) return AllergenIcons.oak;
    if (label.includes('Злаки')) return AllergenIcons.grass;
    if (label.includes('Сорные')) return AllergenIcons.weed;
    if (label.includes('Кладоспориум')) return AllergenIcons.clado;
    if (label.includes('Альтернария')) return AllergenIcons.alt;
    return AllergenIcons.alder;
  };

  return (
    <div className="custom-legend-container" style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginBottom: '15px' }}>
      {Object.entries(groups)
        .sort(([a], [b]) => {
          let iA = groupOrder.indexOf(a); if (iA === -1) iA = 99;
          let iB = groupOrder.indexOf(b); if (iB === -1) iB = 99;
          return iA - iB;
        })
        .map(([groupName, items]) => (
        <div className="legend-group" key={groupName} style={{ display: 'flex', flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: '8px', background: 'transparent', padding: 0, border: 'none', margin: 0 }}>
          {groupName !== 'Деревья' && (
            <div className="legend-group-title" style={{ margin: 0, color: 'var(--text-secondary)', fontSize: '12px', borderBottom: 'none', padding: 0, fontWeight: 500 }}>
              {groupName}:
            </div>
          )}
          {items
            .sort((a, b) => {
              const yearA = parseInt(a.label.match(/\((\d{4})\)/)?.[1] || 0, 10);
              const yearB = parseInt(b.label.match(/\((\d{4})\)/)?.[1] || 0, 10);
              return yearB - yearA;
            })
            .map(ds => {
              const IconComp = getIconForAllergen(ds.label);
              const itemColor = ds.borderColor || ds.backgroundColor || '#fff';
              return (
                <div 
                  key={ds.label} 
                  className={`legend-item${hiddenState[ds.label] ? ' hidden-dataset' : ''}`}
                  onClick={() => toggleFn(ds.label)}
                >
                  <IconComp size={16} color={itemColor} strokeWidth={2.5} style={{ flexShrink: 0 }} />
                  <span className="legend-label">
                    {isArchive ? (ds.label.match(/\((\d{4})\)/)?.[1] || ds.label) : ds.label}
                  </span>
                </div>
              );
            })}
        </div>
      ))}
    </div>
  );
};

export const ChartWithStickyAxis = ({ chartData, chartOptions, type: ChartComponent, leftWidth = '45px' }) => {
  const maskData = {
    ...chartData,
    datasets: chartData.datasets.map(ds => ({
      ...ds,
      borderColor: 'transparent',
      backgroundColor: 'transparent',
      pointRadius: 0,
      pointHoverRadius: 0
    }))
  };

  const maskOptions = {
    ...chartOptions,
    scales: {
      ...chartOptions.scales,
      x: {
        ...(chartOptions.scales?.x || {}),
        ticks: {
          ...(chartOptions.scales?.x?.ticks || {}),
          color: 'transparent'
        }
      }
    },
    plugins: {
      ...chartOptions.plugins,
      tooltip: { enabled: false }
    }
  };

  return (
    <div style={{ position: 'relative', width: '100%' }}>
      <div className="chart-scroll-wrapper custom-scrollbar">
        <div className="chart-container">
          <ChartComponent data={chartData} options={chartOptions} />
        </div>
      </div>
      <div style={{
        position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
        zIndex: 10, pointerEvents: 'none', clipPath: `inset(0 calc(100% - ${leftWidth}) 0 0)`
      }}>
        <div className="chart-scroll-wrapper custom-scrollbar" style={{ overflow: 'hidden' }}>
          <div className="chart-container">
            <ChartComponent data={maskData} options={maskOptions} />
          </div>
        </div>
      </div>
    </div>
  );
};

export const chartOptionsCommon = {
  responsive: true, maintainAspectRatio: false,
  animation: { duration: 800, easing: 'easeOutQuart' },
  interaction: { mode: 'index', intersect: false },
  plugins: {
    legend: { display: false },
    tooltip: {
      backgroundColor: 'rgba(28, 28, 30, 0.95)', titleColor: 'rgba(235, 235, 245, 0.6)', bodyColor: '#fff',
      borderColor: 'rgba(255,255,255,0.15)', borderWidth: 1, padding: 12, boxPadding: 6, usePointStyle: true,
      filter: function(context) {
        if (context.dataset.label.includes('Температура')) return true;
        return context.parsed.y !== null;
      }
    }
  }
};

export const safeVal = (v, scaleType) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  if (isNaN(n)) return null;
  if (scaleType === 'logarithmic' && n <= 0) return null;
  return n;
};
