import React, { useState, useRef, useCallback, useMemo } from 'react';
import { TrendingUp, Leaf } from 'lucide-react';
import { Line } from 'react-chartjs-2';
import { chartOptionsCommon, safeVal } from './ChartUtils';

const DynamicsChartWidget = ({ validHistory, isMobile }) => {
  const [todayScaleType, setTodayScaleType] = useState('linear');
  const [todayTimeRange, setTodayTimeRange] = useState(7);
  const [hiddenDatasetsToday, setHiddenDatasetsToday] = useState({});
  const tooltipTimeout = useRef(null);

  const autoHideTooltipHandler = useCallback((context) => {
    if (tooltipTimeout.current) clearTimeout(tooltipTimeout.current);
    if (context.tooltip.opacity > 0) {
      tooltipTimeout.current = setTimeout(() => {
        if (context.chart) {
          context.chart.tooltip.setActiveElements([], { x: 0, y: 0 });
          context.chart.setActiveElements([]);
          context.chart.update();
        }
      }, 3000);
    }
  }, []);

  const toggleHiddenDatasetToday = useCallback((lbl) => {
    setHiddenDatasetsToday(p => ({ ...p, [lbl]: !p[lbl] }));
  }, []);

  const recentHistory = useMemo(() => {
    let history = [...validHistory];
    if (todayTimeRange !== 'all') {
      history = history.slice(0, Number(todayTimeRange));
    }
    return history.reverse();
  }, [validHistory, todayTimeRange]);

  const todayChartData = {
    labels: recentHistory.map(d => {
      if (!d || typeof d.date !== 'string') return '';
      const parts = d.date.split('-');
      if (parts.length !== 3) return d.date;
      return `${parts[2]}.${parts[1]}.${parts[0].slice(-2)}`;
    }),
    datasets: [
      { label: 'Ольха', data: recentHistory.map(d => safeVal(d.alder, todayScaleType)), borderColor: '#32D74B', backgroundColor: 'rgba(50,215,75,0.2)', fill: true, tension: 0.4, pointRadius: isMobile ? 1.5 : 4, pointHoverRadius: isMobile ? 3 : 6, borderWidth: isMobile ? 1.5 : 2.5 },
      { label: 'Орешник', data: recentHistory.map(d => safeVal(d.hazel, todayScaleType)), borderColor: '#FFD60A', backgroundColor: 'rgba(255,214,10,0.2)', fill: true, tension: 0.4, pointRadius: isMobile ? 1.5 : 4, pointHoverRadius: isMobile ? 3 : 6, borderWidth: isMobile ? 1.5 : 2.5 },
      { label: 'Береза', data: recentHistory.map(d => safeVal(d.birch, todayScaleType)), borderColor: '#FF453A', backgroundColor: 'rgba(255,69,58,0.2)', fill: true, tension: 0.4, pointRadius: isMobile ? 1.5 : 4, pointHoverRadius: isMobile ? 3 : 6, borderWidth: isMobile ? 1.5 : 2.5 },
      { label: 'Дуб', data: recentHistory.map(d => safeVal(d.oak, todayScaleType)), borderColor: '#15803d', backgroundColor: 'rgba(21,128,61,0.2)', fill: true, tension: 0.4, pointRadius: isMobile ? 1.5 : 4, pointHoverRadius: isMobile ? 3 : 6, borderWidth: isMobile ? 1.5 : 2.5 }
    ]
  };

  const activeTodayChartData = {
    ...todayChartData,
    datasets: todayChartData.datasets.map(ds => ({ ...ds, hidden: !!hiddenDatasetsToday[ds.label] }))
  };

  const todayChartOptions = useMemo(() => ({
    ...chartOptionsCommon,
    scales: {
      x: { 
        grid: { display: false }, 
        ticks: {
          color: context => {
            const dateStr = recentHistory[context.index]?.date;
            if (!dateStr) return '#EBEBF599';
            const dayOfWeek = new Date(dateStr + 'T00:00:00').getDay();
            return (dayOfWeek === 6 || dayOfWeek === 0) ? '#FFFFFF' : '#EBEBF599';
          },
          font: context => {
            const dateStr = recentHistory[context.index]?.date;
            if (!dateStr) return { weight: 'normal' };
            const dayOfWeek = new Date(dateStr + 'T00:00:00').getDay();
            return { weight: (dayOfWeek === 6 || dayOfWeek === 0) ? 'bold' : 'normal' };
          }
        }
      },
      y: { type: todayScaleType, min: todayScaleType === 'logarithmic' ? 0.5 : 0, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#EBEBF599', callback: v => todayScaleType === 'logarithmic' ? [1,10,100,1000,10000].includes(v) ? v : null : v } }
    },
    plugins: {
      ...chartOptionsCommon.plugins,
      tooltip: {
        ...chartOptionsCommon.plugins.tooltip,
        external: autoHideTooltipHandler,
      }
    },
  }), [todayScaleType, recentHistory, autoHideTooltipHandler]);

  return (
    <div className="card overflow-hidden w-full">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 15, flexWrap: 'wrap', gap: '10px' }}>
        <h3 className="section-title" style={{ margin: 0 }}><TrendingUp size={18} /> Динамика пыления</h3>
        <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
          <div className="segment-control" style={{ width: 90, padding: 2, flexShrink: 0, height: 26 }}>
            <div className="segment-indicator" style={{ transform: `translateX(${todayScaleType === 'linear' ? 0 : 100}%)`, width: 'calc(50% - 2px)', background: '#48484A' }}></div>
            <button className={`segment-btn ${todayScaleType==='linear'?'active':''}`} onClick={() => setTodayScaleType('linear')} style={{ fontSize: 10, padding: 0, lineHeight: '22px' }}>LIN</button>
            <button className={`segment-btn ${todayScaleType==='logarithmic'?'active':''}`} onClick={() => setTodayScaleType('logarithmic')} style={{ fontSize: 10, padding: 0, lineHeight: '22px' }}>LOG</button>
          </div>
          <select value={todayTimeRange} onChange={(e) => setTodayTimeRange(e.target.value === 'all' ? 'all' : Number(e.target.value))} style={{ background: 'rgba(255, 255, 255, 0.1)', color: 'var(--text-main)', border: 'none', borderRadius: '8px', padding: '0 10px', fontSize: '12px', outline: 'none', cursor: 'pointer', height: 26 }}>
            <option value={7} style={{ color: '#000' }}>Неделя</option>
            <option value={30} style={{ color: '#000' }}>Месяц</option>
            <option value="all" style={{ color: '#000' }}>Все время</option>
          </select>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '15px' }}>
        {todayChartData.datasets.map(ds => {
          const isHidden = !!hiddenDatasetsToday[ds.label];
          const isOak = ds.label === 'Дуб';
          return (
            <button
              key={ds.label}
              onClick={() => toggleHiddenDatasetToday(ds.label)}
              style={{
                display: 'flex', alignItems: 'center', gap: '6px',
                background: isHidden ? 'rgba(255,255,255,0.05)' : ds.backgroundColor,
                border: `1px solid ${isHidden ? 'transparent' : ds.borderColor}`,
                borderRadius: '12px', padding: '4px 10px',
                color: isHidden ? 'var(--text-secondary)' : '#fff',
                cursor: 'pointer', transition: '0.2s',
                fontSize: '12px', fontWeight: 600,
                opacity: isHidden ? 0.5 : 1
              }}
            >
              {isOak ? (
                <Leaf size={14} color="#15803d" fill="#15803d" />
              ) : (
                <div style={{ width: 8, height: 8, borderRadius: '50%', background: isHidden ? '#8e8e93' : ds.borderColor }} />
              )}
              {ds.label}
            </button>
          );
        })}
      </div>

      <div className="chart-container" style={{ position: 'relative', width: '100%', maxWidth: '100%', height: '300px', minWidth: 0 }}>
        <Line data={activeTodayChartData} options={todayChartOptions} />
        {activeTodayChartData.labels.length === 0 && (
          <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(28,28,30,0.6)', backdropFilter: 'blur(2px)', borderRadius: 12, color: 'var(--text-main)', fontSize: 14, textAlign: 'center', padding: 20 }}>
            База данных пуста.<br/>Нажмите «+» в правом верхнем углу, чтобы внести первые замеры.
          </div>
        )}
      </div>
    </div>
  );
};

export default DynamicsChartWidget;